(function(){var d={"book": {"chapters": [{"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-primogen-s-gambit.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit", "page": 4, "roots": ["#vFs2tu8Gcwz4IsZJ07brvVv"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-prologue-crew-expendable.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Prologue: Crew Expendable", "page": 6, "roots": ["#v6Eb692gof3fSrTZ7XBEr4n", "#vHJzn6fgiCieJFIFJPolMaW"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-chapter-one-the-blue-moon.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Chapter One: The Blue Moon", "page": 10, "roots": ["#vDjho3Auz2CDbAFpGHbCdZ0", "#vYon7x7B7vCiRqtWgtFqA6V", "#vV2YkMq5mBpZBT3WxdLeKzN", "#vwujkwfzTxlK1SThw27YHpZ", "#vwvCZU6owZbh7ADnB8ZToJW"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-chapter-two-busted.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Chapter Two: Busted!", "page": 16, "roots": ["#vKH2yWMDJrQdYj7OFAQ9AAR", "#vwZ6vhhAZ3g6TwbFFOrWhDd", "#v33kPFAe4deENbtG1H7f5Ey"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Chapter Three: All About Archangel", "page": 19, "roots": ["#vmXkBxCDkVJek5WS3R1F9ON", "#vsvbZBIHPmkJnD6wLFaNDGA", "#vAFT30HHVFFGaXECKrPiA67", "#vNTSNkyXFZgEb8Rf7wJgmjc"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-chapter-four-parlor-games.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Chapter Four: Parlor Games", "page": 22, "roots": ["#vXEn3eJgxDfztwnGwXULiXu", "#vuZI6YqLChYOLPaNbtdWfzM", "#vrcP9gF3O5SZ88I0wxoKown"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-chapter-five-tumbling-down.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Chapter Five: Tumbling Down", "page": 24, "roots": ["#vlbPlOBNb6yGpRb6Wqn0GQW", "#v1zn2IGCOlkdVLDHwQMovAU", "#vk8cfg1Us6YfaDl3kJtCJsH", "#vmid1eRAWZzAODwTA2bIeeB"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-epilogue-domino-effect.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Epilogue: Domino Effect", "page": 26, "roots": ["#vwWp5HTSUrGO5nXb9dR8sVR"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Appendix One: Allies & Antagonists", "page": 27, "roots": ["#vD12wS57U3YFJQK25r2b10Y", "#vQHQ8WJe1NGQRUjp79UhPyr", "#vTuZ5ItcaLtZFNBv5aRyn8E", "#vF9hcCMAwKiXhj2ZRmvQkPG"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Appendix Two: Player Character Coterie", "page": 29, "roots": ["#vGqssn8r9cEVGpLwCfUcL9I", "#vh3bx91dcPzgZupqKROyOic", "#vkRaOAwdTlR1ocYpki9xymB", "#vDIKp4PAdT13Hj5bxo5HAFG", "#vbRq5qd0V8AaoAQZcopYCrU", "#vZzfYF1x0fdylriKrDh1HLZ", "#vhYWWgzYEHkBucDIW70q4UH"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-primogens-gambit-appendix-three-adaptations.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Primogen's Gambit - Appendix Three: Adaptations", "page": 33, "roots": ["#vvjGGE4ZJapNbxR8qTqJvgQ", "#vgMWTDcSDJsabjj9qo4jAAH", "#vUdwLDrkA0lB8lpkEwTweBc", "#v6yAoL9OkD6Vvr8dFbljFfL"]}], "entities": ["#vFs2tu8Gcwz4IsZJ07brvVv", "#v6Eb692gof3fSrTZ7XBEr4n", "#vHJzn6fgiCieJFIFJPolMaW", "#vDjho3Auz2CDbAFpGHbCdZ0", "#vYon7x7B7vCiRqtWgtFqA6V", "#vV2YkMq5mBpZBT3WxdLeKzN", "#vwujkwfzTxlK1SThw27YHpZ", "#vwvCZU6owZbh7ADnB8ZToJW", "#vKH2yWMDJrQdYj7OFAQ9AAR", "#vwZ6vhhAZ3g6TwbFFOrWhDd", "#v33kPFAe4deENbtG1H7f5Ey", "#vmXkBxCDkVJek5WS3R1F9ON", "#vsvbZBIHPmkJnD6wLFaNDGA", "#vAFT30HHVFFGaXECKrPiA67", "#vNTSNkyXFZgEb8Rf7wJgmjc", "#vXEn3eJgxDfztwnGwXULiXu", "#vuZI6YqLChYOLPaNbtdWfzM", "#vrcP9gF3O5SZ88I0wxoKown", "#vlbPlOBNb6yGpRb6Wqn0GQW", "#v1zn2IGCOlkdVLDHwQMovAU", "#vk8cfg1Us6YfaDl3kJtCJsH", "#vmid1eRAWZzAODwTA2bIeeB", "#vwWp5HTSUrGO5nXb9dR8sVR", "#vD12wS57U3YFJQK25r2b10Y", "#vQHQ8WJe1NGQRUjp79UhPyr", "#vTuZ5ItcaLtZFNBv5aRyn8E", "#vF9hcCMAwKiXhj2ZRmvQkPG", "#vGqssn8r9cEVGpLwCfUcL9I", "#vh3bx91dcPzgZupqKROyOic", "#vkRaOAwdTlR1ocYpki9xymB", "#vDIKp4PAdT13Hj5bxo5HAFG", "#vbRq5qd0V8AaoAQZcopYCrU", "#vZzfYF1x0fdylriKrDh1HLZ", "#vhYWWgzYEHkBucDIW70q4UH", "#vvjGGE4ZJapNbxR8qTqJvgQ", "#vgMWTDcSDJsabjj9qo4jAAH", "#vUdwLDrkA0lB8lpkEwTweBc", "#v6yAoL9OkD6Vvr8dFbljFfL"], "id": "primogens-gambit", "kind": "book", "label": "The Primogen’s Gambit"}, "entities": {"#v1zn2IGCOlkdVLDHwQMovAU": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "The coterie lays out their evidence and hopes the Camarilla Court will listen.\n\nThis is a Social Conflict between the coterie and Archangel. Any guard still loyal to him assists him. He defends himself with what he’s done for the Camarilla and attacks with claims of an Anarch conspiracy against him. The coterie attacks with their experiences in the story; their successes provoke visible reactions of rage and disgust among the Kindred present. Any piece of evidence on hand counts as a one-use +1 Willpower damage weapon; evidence can be given additional weight according to Table 2, p. 14. Take into account any preparations the group has made before being called out in the VIP room, especially when determining consequences for dramatic successes or failures. Due to the intense scrutiny, once a character is out of Willpower, they’re out of the scene and someone else needs to step up to present evidence.\n\nThere’s a nearby laptop connected to a projector the coterie can use. The *Social Combat* section of **Vampire: The Masquerade (**p. 304) has suggestions for building dice pools according to the characters’ approach. This scene can provide an opportunity for creative players to put some of their less frequently used skills into play, such as the pre-generated Vengeful Occultist’s skill in Academics (teaching) to lay out the evidence for the Camarilla. The coterie can benefit from teamwork (**Vampire,** p. 122) as narratively appropriate.\n\nThe coterie wins if they inflict the most Willpower damage after three rounds. The Camarilla upper crust believes them, and Paul steps in to subdue Archangel. His fate depends on his Willpower track. If he has any free boxes left, he’ll be exiled from the domain. If his Willpower is Impaired, he’s facing the sun or a blood hunt, something the Prince decides later. However it ends, Paul gives the coterie a running start. The club is no longer an Elyisum, and the coterie is still a threat.\n\nThe coterie loses if they take the most Willpower damage after three rounds. Avery pledges an investigation but declares that Archangel gets to remain free. He demands a seat on the Primogen. He gets a chilly reception and it’s clear that he’s no longer the shoo-in he seemed only a few minutes ago. The coterie can accept this (and take advantage of that running start to get out) or escalate to force in *Killing Archangel,* p. 25.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-five-tumbling-down.ttrpg", "form": "DEF", "guidance": [], "id": "#v1zn2IGCOlkdVLDHwQMovAU", "key": "Exposing Archangel", "name": "Exposing Archangel", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v2mPLOr7KPvwTzBn9gOCy3A": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "The Anarchs sent the coterie on this assignment because of their relative anonymity in the city, but some plans might need more people power. If the characters look for back-up, these are their options.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "form": "DEF", "guidance": [], "id": "#v2mPLOr7KPvwTzBn9gOCy3A", "key": "Back-Up", "name": "Back-Up", "parent": "#vAFT30HHVFFGaXECKrPiA67", "props": [{"name": "Captain and the Anarchs", "type": "STRING", "value": "The coterie’s burner phone puts them in touch with Snap, which also gives them a line to Captain. The Anarchs aren’t willing to go to the Waterfall Parlor if the coterie’s planning to kill Archangel outright, but they might support plans to kidnap him if given a very good reason (e.g. Archangel’s plans with the FBI or the murder of a thin-blood). They are willing to show up in an official capacity for more peaceful plans.", "vk": "scalar"}, {"name": "Allies, Contacts, and Retainers", "type": "STRING", "value": "Any Allies (*Vampire*, pp. 184–185) are willing to answer a call for help, as are Retainers. If a character’s Contact is especially close, they could assist at the Storyteller’s discretion, but in general they only provide material support or information. Getting mortals into Elysium poses its own challenges and probably isn’t on the table for one-shot play. The pre-generated characters’ relevant Contacts are as follows: the Zealous Reformer has Contacts among local activists, the Rugged Survivalist has Contacts among gang members (the Westside Kings), and the Soft-Hearted Detective has a private investigator as a Contact.", "vk": "scalar"}, {"name": "Turned Assets", "type": "STRING", "value": "If the coterie were able to turn Adriana or her guards to their side in **Chapter Two**, they’re willing to provide support in secret. Adriana still feels great affection for her domitor and won’t have any part in any violent plan, but would be willing to reveal his operation. The guards are willing to help in any plan the coterie thinks of.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v33kPFAe4deENbtG1H7f5Ey": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "If the coterie tries to escape or attacks Adriana or the vampire guards, they enter a Physical Conflict. Any chance to shift into a Social Conflict is gone, but they aren’t trying to kill the coterie. Their priority is recovering any evidence the coterie took and destroying it. If they can capture any characters and present them to Archangel, even better.\n\nAdriana and the guards try their best to keep the fight to the basement. If the coterie moves the fight into the bar, they’ll back off but threaten to call the police. Given the bodies in the basement, this is likely a bluff on Adriana’s part, but an alarmed mortal bartender might, which could post a Masquerade risk the coterie likely can’t afford to run. They’ll continue to fight if the conflict moves to the alley but limit their Discipline use. Once it’s clear that the coterie’s out of the alley or bar, they won’t pursue. The guards take some time to figure out who the coterie is and where their havens might be, but that’s a problem for another night.\n\nThe conflict lasts for three rounds. The coterie wins under two conditions: their opponents suffer the most damage, or they’re able to escape the basement through one or both of its exits. If the coterie doesn’t already have weapons, there’s a set of surgical tools nearby one of the gurneys with three scalpels that serve as a +1 Superficial Physical damage melee weapon. If they defeat Adriana and search her pockets, they find a golden business card.\n\nThe coterie loses the conflict if they take more Health damage than their opponents after three rounds, or if every character is restrained or otherwise unable to act. The guards search the coterie and take their weapons and anything on their person that seems like it might take pictures or hold information. A Wits + Stealth test at Difficulty 4 lets the coterie hide their things while the guards pat them down. The coterie can win at a cost on this roll: they may keep evidence on them equal to their rolled successes minus 1. If the entire coterie only has a single piece of evidence, the test is at Difficulty 2 instead, with options for winning at a cost (anything from taking damage to leaving behind evidence of their own presence) if they fail. Unless this is part of a longer chronicle, with options for the coterie to pursue other angles of investigation with help from Captain, the coterie cannot progress in the story without at least one piece of evidence, even if it’s being held by a captured character.\n\nIf Adriana and the guards restrained one or more characters at the end of the conflict, the guards capture them. The remaining characters may make one last Strength + Brawl test to rescue them at Difficulty 3; after this, either mortal authorities called by the bartenders or additional backup from the Midnight Angels arrive, forcing them to flee or surrender. A character may only rescue one captured member at a time. Failure could get the would-be rescuers captured as well, and bestial failures or messy criticals could be especially dangerous if the fight is taking place inside the bar.\n\nIf any of the coterie’s captured, it’s not the end for them. Archangel plans to use them as unscheduled entertainment in his Elysium, giving them a chance to learn the whole plan in **Chapter Three** and to escape and aid the rest of the coterie in **Chapter Four**. After escaping from the Blue Moon with something to", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-two-busted.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#v33kPFAe4deENbtG1H7f5Ey", "name": "Physical Conflict"}], "id": "#vbm9mQUW5r9gRuHoUrZ8H4U", "name": "Adjusting for Time", "text": "The Storyteller has a lot of discretion here when it comes to letting the fight run longer or ending it quickly by summoning mortal police or Kindred antagonists. If pressed for time, consider keeping the party together. If overwhelming force arrives, all characters can be captured and brought together to the locked room in the Waterfall Parlor, bypassing the ***Following Up*** and ***Arranging Preparations*** sections of the story entirely. Otherwise, any captures can be converted into costly escapes — possibly by having those characters leave something behind that implicates them in the break-in or the trafficking operation itself — so that the coterie moves together into Chapter Three. If the party is split between captured and escaped characters, the Storyteller should be mindful of pacing in Chapter Three. Don’t keep any players’ characters out of play for too long, and if there’s time, encourage any captured characters’ efforts to make the most of their situation tactically.", "topics": []}], "id": "#v33kPFAe4deENbtG1H7f5Ey", "key": "Physical Conflict", "name": "Physical Conflict", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v5O9hA33y4F9vDCUQjCaicu": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Brenton’s been dreaming about this moment since the night he was Embraced. The Toreador has spent years building a base of power and bringing all kinds of Kindred to his side. Outwardly, he presents himself in a genteel and respectful manner, even to the Anarchs he loathes. His image is that of a “moral vampire,” a man of honor among kine and Kindred. He’s so dedicated to it that it’s almost believable. But the skeletons in his closet, both metaphorical and literal, threaten to tear him down, and the Anarchs see that it does.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#v5O9hA33y4F9vDCUQjCaicu", "key": "Brenton “Archangel” Finlay", "name": "Brenton “Archangel” Finlay", "parent": "#vQHQ8WJe1NGQRUjp79UhPyr", "props": [{"name": "General Difficulty", "type": "STRING", "value": "5 / 3", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "2", "vk": "scalar"}, {"name": "Standard Dice Pools", "type": "STRING", "value": "Physical 4, Social 6, Mental 5", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 5, Willpower 5", "vk": "scalar"}, {"name": "Exceptional Dice Pools", "type": "STRING", "value": "Firearms 6, Intimidation 7, Persuasion 6, Subterfuge 8", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Auspex 2, Celerity 3, Presence 3", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v6Eb692gof3fSrTZ7XBEr4n": {"aliases": null, "book": "primogens-gambit", "children": ["#vOQbLkwCfSVa0lIarjCFdJx"], "choices": [], "desc": "The story begins when the coterie gathers in a freezer in the back of a local supermarket that’s seen better days. Read or paraphrase:\n\n*It’s a warm summer night, but you’re standing in a meat freezer in the back of a Herrick’s, a grocery store that some of you might have used when you were alive. As Kindred, you know that it’s the so-called headquarters of the city’s Anarch movement, which you belong to by choice or by force. You were invited here by an anonymous coded text, or a passed-on paper note for “a way to get your name out and strike at the Cammies.”*\n\n*It’s you and a few others that you might have recognized on night-to-night hunts, but never had the chance to greet. Why not say hello?*\n\nGive the players a few moments to get into character. How and why did each member receive their anonymous invitation? Suggestions are provided in the descriptions of each pre-generated character (see *Appendix Three*,), but players should feel free to improvise here as well. If your troupe has a relationship map, this is a great way to feel out how those relationships work out at the table. If any coterie member (such as the pre-generated Domineering Opportunist character) has Sense the Unseen (*Vampire: The Masquerade***,** p. 243), give them a chance to detect Snap (p. 28) with a hidden test of Wits + Auspex at Difficulty 3; otherwise, characters actively searching for hidden entities can test Resolve + Auspex at Difficulty 2. They’ve been standing in front of the coterie as they gather, which the vampire realizes as soon as they see them.\n\nAfter Snap is detected or after the characters have had a chance to introduce themselves, read out or paraphrase:\n\n*You hear a voice that sounds like gravel whirling in a blender. “They’re here, Captain.”*\n\n*Your mind suddenly registers the appearance of a tall figure, their hoodie pulled up so tight that you can only get a glimpse of their milky grey eyes.*\n\n*A Black woman wearing a Herrick’s uniform steps into the freezer. “Thanks, Snap.”*\n\n*She turns to address you all. “I won’t waste your time. We’ve taken a vote, and you’re drafted.”*\n\nCaptain explains the situation as best she can. Through questions and conversation with the two Anarchs, make sure that the players have the following information:\n\ninformation worth having.\n\nCaptain makes her request: get into Elysium during the Camarilla’s meeting. By any means necessary, the coterie must make sure that Archangel’s bid for the Primogen is either rejected, or that he never gets the chance to make the bid at all. She, Snap, and the other Anarch leaders believe that since the coterie is under the Camarilla’s radar, they’ll be able to act in ways the rest of the sect can’t. She’ll suggest investigating the Blue Moon first, as the Waterfall Parlor has additional security measures in place (detailed in *Arranging Preparations,* p. 20), but she’s open to whatever the coterie suggests doing after that. She assures the coterie that if they pull this off, the city’s Anarchs are in their debt; as leader, Captain can offer rewards in line with the characters’ individual motivations (see the table at the end of this section), or other rewards that might entice players in a longer chronicle (status, domain access, protection, and so forth).\n\nSnap gives the coterie a plastic bag containing a digital camera, a thumb drive, and a burner phone. They suggest using the camera and thumb drive in case there’s anything worthwhile in the Blue Moon’s basement, reminding the coterie that it’s better to destroy evidence than to make a copy, lose it, and put the Masquerade at risk. The coterie also has their own equipment (see the *Equipment and Preparedness Tests* sidebar, p. 7), but if they’re found responsible for the final death of another Kindred, the Camarilla won’t hesitate to invoke *lex talionis*: the Blood Hunt.\n\nCaptain gives them the addresses of the Blue Moon and the Waterfall Parlor. Once they hand off the items and addresses, the two Anarchs leave the coterie to their work in **Chapter One**.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-prologue-crew-expendable.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#v6Eb692gof3fSrTZ7XBEr4n", "name": "Prologue: Crew Expendable"}], "id": "#vXfU4VMyu8boMTpmwY2PQ0n", "name": "Adjusting for Time", "text": "If you’re short on time or the players seem reluctant to roleplay so much so early, have them meet here to plan. The introduction to Captain can be played as a flashback, in which characters each ask one question or share information that their backstories might give them access to. If you’re using the pre-generated characters, the Rugged Survivalist could have information on Archangel’s shady business through his contacts in the Westside Gang, or the Charming Impresario might know of the dive bar’s recent purchase and efforts to attract younger clients from their background as a producer. The Domineering Opportunist with enemies in the Camarilla could know about the recent disappearance of a Primogen, and so on. The table of rewards and threats at the end of this section are written with the concepts of the pre-generated Kindred in mind but are general enough to serve as a random table for enticing (or coercing) any coterie to take up Captain’s quest. If all else fails, putting a character’s Touchstone in harm’s way is usually an effective goad to action.", "topics": []}, {"concerns": [{"hash": "#v6Eb692gof3fSrTZ7XBEr4n", "name": "Prologue: Crew Expendable"}], "id": "#vGZLVgwfDhjCTUsKNnnowai", "name": "Equipment and Preparedness Tests", "text": "In general, Vampire: The Masquerade assumes characters have basic items and equipment associated with their character; Kindred with several dots in Firearms are unlikely to go on a mission without their weapon, and the Nosferatu detective doesn’t need to specify that he’s carrying his lock picks. For less plausible items, use suggestions from ***Preparedness*** (Vampire, p. 410), or have characters make a Wits + Streetwise test of an appropriate Difficulty to see if they have access to what they need in the moment. For tasks that use specialized equipment (such as picking a physical lock or bypassing an electronic one), the Storyteller may apply a +1 Difficulty modifier for improvised or unreliable tools.", "topics": []}], "id": "#v6Eb692gof3fSrTZ7XBEr4n", "key": "Prologue: Crew Expendable", "name": "Prologue: Crew Expendable", "parent": null, "props": [{"items": [{"value": "The local Camarilla elite have had an uneasy peace with the Anarchs since falling out years ago, but the recent disappearance of one of their Primogen could end that peace.", "vk": "scalar"}, {"value": "There’s an open spot on the city’s Primogen council, one that Archangel (pp. 27) wants for himself. The Primogen council is composed of four Kindred, each representing the strongest coterie in the four corners of the city, and their Toreador representative has recently gone missing.", "vk": "scalar"}, {"value": "Archangel is an upstanding Camarilla member and considered a moral figure to their community. He’s convinced the Prince to declare the jazz club he owns, the Waterfall Parlor, as Elysium for the sect.", "vk": "scalar"}, {"value": "Tomorrow night (or in a few hours if this story is set over one night) he’ll make his move to join the Primogen at the monthly Camarilla meeting in his jazz club. They’ll most likely accept this.", "vk": "scalar"}, {"value": "Archangel’s known for his hostility towards the Anarchs. He’s made it known that he wants them gone, and that position of power could let him do all kinds of terrible things with the Prince’s permission (see the table of rewards and threats below).", "vk": "scalar"}, {"value": "A week ago, Snap found Archangel going in and out of a basement beneath the Blue Moon, a dive bar downtown. No one, not even Snap’s sources in the Camarilla, realized he had a stake in the place until they found a variation of his Mask, Mike Baker, in the bar’s records.", "vk": "scalar"}, {"value": "Two nights ago, members of Archangel’s coterie, the Midnight Angels, attacked Snap in their Haven. Similar attacks happened to other well-known or outspoken Anarchs.", "vk": "scalar"}, {"value": "Whatever Archangel has going on in that basement is something he’s willing to tarnish his reputation and threaten the city’s peace for. That might be", "vk": "scalar"}, {"value": "Archangel must be kept out of the Primogen at all costs.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v6yAoL9OkD6Vvr8dFbljFfL": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Brenton probably chose the name *Archangel* and *Midnight Angels* because they sounded cool, like many young Kindred. He is woefully ignorant of his clan’s history and previous Toreador using the word *angel*. This could cause added conflict with any members of the Nephilim cult, also known as the Children of the Angel (see *Cults of the Blood Gods, pp. 105–114*). One or more Nephilim believers may take offense at the name or have manipulated Brenton into serving as their unwitting pawn.\n\nSandman Aliyah “Princess” Shaw Domineering Opportunist Name Concept Predator The Primogen's Gambit Ventrue Become Baron of this charming little city Chronicle Ambition Clan Julian Howard 12th Sire Desire Generation ATTRIBUTES Physical Social Mental Strength Charisma Intelligence ●●○○○ ●●●●○ ●○○○○ Dexterity Manipulation Wits ●●○○○ ●●●○○ ●●○○○ Stamina Composure Resolve ●●○○○ ●●●○○ ●●○○○ Health Willpower □□□□□ ■■■■■ □□□□□ ■■■■■ SKILLS Athletics ●●○○○ Animal Ken ○○○○○ Academics ○○○○○ Brawl ○○○○○ Etiquette ●●●○○ Awareness ○○○○○ Craft ○○○○○ Insight ○○○○○ Finance ○○○○○ Drive ●○○○○ Intimidation ●●○○○ Investigation ○○○○○ Firearms ●●○○○ Leadership ●●●○○ Medicine ○○○○○ Melee ○○○○○ Performance ○○○○○ Occult ○○○○○ Larceny ●●○○○ Persuasion ●●●●○ Politics ○○○○○ Stealth Break-Ins ●○○○○ Streetwise ○○○○○ Science ○○○○○ Survival ○○○○○ Subterfuge ●●●○○ Technology ○○○○○ DISCIPLINES Auspex Dominate Fortitude ●○○○○ ●●○○○ ●○○○○ Sense the Unseen Compel Unswayable Mind Mesmerize ○○○○○ ○○○○○ ○○○○○ © 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nChronicle Tenets Touchstones & Convictions Clan Bane Always keep your sworn word — Rob Watson, distant relative but close friend.\n\nDrinking mortal blood outside their preference costs Willpower points equal the Bane Severity or the blood taken surges back up as scarlet vomit. With a Resolve + Awareness test (Difficulty 4 or more) your character can sense if a mortal possesses the blood they require. Feeding from non-preferred victims Looks (Beautiful)\n\nAdvantages & Flaws\n\nResources\n\nHaven (Crash Pad: Size Small, Luxury, — security system)\n\n-Adversary (Julian Howard, sire)\n\nNotes\n\n●●○○○\n\n●●●●○\n\n●●●○○\n\n○○○○○\n\n○○○○○\n\n●●○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\nBlood Potency ●○○○○ ○○○○○ Blood Surge Mend Amount Add 2 dice 1 point Superficial Power Bonus Rouse Re-Roll None Level 1 Feeding Penalty Bane Severity No Effect 2 Total Experience Spent Experience True age Apparent age Date of birth Date of death Appearance 2002 2020 Distinguishing features History Aliyahʼs life and unlife were decided for her. The youngest in a family of Ghouls, the blood-addicted servants of a vampire, her sire hand-picked her for a promotion into undeath. The Camarilla was fun, but any path to greater power was cut off by older vampires of greater stature. Realizing that that anyone in the Anarchs could rise through sheer gumption, she knew what to do. Her sire and her family are pissed, but theyʼre far away now. Her invitation to the Anarch gathering arrives on Julian Howardʼs letterhead. She gets ready to move to a new crash pad, again, but the envelope is empty, a timestamp written on the inside. When she reviews that moment on her home security system footage, the camera is covered, only for an instant, by a piece of paper bearing the details of the Anarch meeting.\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nZealous Reformer Ben “Freebird” Irwin Scene Queen (Local Activists)\n\nName Concept Predator\n\nThe Primogen's Gambit Brujah Tear down any system that exploits the weak.\n\nChronicle Ambition Clan\n\n13th\n\nSire Desire Generation\n\nATTRIBUTES\n\nPhysical Social Mental Strength Charisma Intelligence ●●●○○ ●●○○○ ●●○○○ Dexterity Manipulation Wits ●●●●○ ●●○○○ ●●○○○ Stamina Composure Resolve ●●●○○ ●○○○○ ●●○○○ Health Willpower □□□□□ □■■■■ □□□■■ ■■■■■ SKILLS Athletics ●●●●○ Animal Ken ○○○○○ Academics Research ●○○○○ Brawl ●●●○○ Etiquette ○○○○○ Awareness ●○○○○ Craft ○○○○○ Insight ○○○○○ Finance ○○○○○ Drive ●●●○○ Intimidation ●●●○○ Investigation ○○○○○ Firearms ○○○○○ Leadership ●●○○○ Medicine ●○○○○ Local Activists First Aid Melee ●●○○○ Performance ○○○○○ Occult ○○○○○ Larceny ○○○○○ Persuasion ○○○○○ Politics ○○○○○ Stealth ○○○○○ Streetwise ●●○○○ Science ○○○○○ Survival ○○○○○ Subterfuge ○○○○○ Technology ○○○○○ DISCIPLINES Celerity Potence ●●○○○ ●●○○○ ○○○○○ Cat's Grace Soaring Leap Fleetness Prowess ○○○○○ ○○○○○ ○○○○○ © 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nChronicle Tenets Touchstones & Convictions Clan Bane Protect the innocent from harm. Alex Lee, long-suffering single father.\n\nSubtract dice equal to the Bane Severity of the Brujah from any roll to resist fury frenzy. This cannot take the pool below one die Advantages & Flaws Fame (Local Activists)\n\nContact (Local Activists)\n\nHaven (Rented House: Good Size, Library)\n\nResources\n\nHerd (Local Activists)\n\n-Disliked (City Government)\n\n-Known Blankbody\n\nNotes\n\n●○○○○\n\n●○○○○\n\n●●●○○\n\n●●○○○\n\n●●○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\nBlood Potency ●○○○○ ○○○○○ Blood Surge Mend Amount Add 2 dice 1 point Superficial Power Bonus Rouse Re-Roll None Level 1 Feeding Penalty Bane Severity No Effect 2 Total Experience Spent Experience True age Apparent age Date of birth Date of death Appearance 1996 2016 Distinguishing features History From an early age, Ben knew that the world was unfair. He thought he could change the system from the inside as a local politicianʼs aide, but a bad night and the Embrace of a Camarilla loyalist seeking power over his boss proved the worldʼs corruption went deeper than he imagined. Free of his sireʼs control, he wonʼt make the same mistake twice. His invitation to the Anarch gathering arrives by bike messenger, slipped into a delivery order for his activist housemates. The note scrawled on the receipt mentions information about a local protestor whose disappearance has his Herd worried.\n\n© 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nVengeful Occultist Cleaver Daniella “Ley Line” Newton Name Concept Predator The Primogen's Gambit Caitiff Create a unified theory of the supernatural Chronicle Ambition Clan 12th Sire Desire Generation ATTRIBUTES Physical Social Mental Strength Charisma Intelligence ●○○○○ ●●○○○ ●●●○○ Dexterity Manipulation Wits ●●○○○ ●●○○○ ●●●○○ Stamina Composure Resolve ●●○○○ ●●○○○ ●●●●○ Health Willpower □□□□□ ■■■■■ □□□□□ □■■■■ SKILLS Athletics ●●○○○ Animal Ken ○○○○○ Academics Teaching ●●●○○ Brawl ○○○○○ Etiquette ○○○○○ Awareness ●●●○○ Craft ○○○○○ Insight ●●●○○ Finance ○○○○○ Drive ○○○○○ Intimidation ○○○○○ Investigation ●○○○○ Firearms ●●○○○ Leadership ○○○○○ Medicine ●○○○○ Melee ○○○○○ Performance ○○○○○ Occult ●●●●○ Larceny ○○○○○ Persuasion ○○○○○ Politics ○○○○○ Stealth Hiding ●○○○○ Streetwise ○○○○○ Science ○○○○○ Survival ○○○○○ Subterfuge Coverups ●●○○○ Technology ○○○○○ DISCIPLINES Animalism Blood Sorcery Celerity ●○○○○ ●●○○○ ●○○○○ Bond Famulus: Bobbi, family Great Dane A Taste for Blood Rapid Reflexex Extinguish Vitae ○○○○○ Blood Sorcery Rituals ○○○○○ ○○○○○ Clinging of the Insect © 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nChronicle Tenets Touchstones & Convictions Clan Bane The guilty must be punished — Taylor Reed, last remaining mortal descendant of her sire.\n\nThe Storyteller may always impose a one or two dice penalty on Social tests against fellow Kindred who know they are Caitiff, regardless of their eventual Status.\n\nAdvantages & Flaws\n\nLinguistics: German, French, Spanish Haven (Family Guest Home: Good Size)\n\nHerd\n\nResources\n\n-Dark Secret (Cleaver)\n\n-Suspect\n\nNotes\n\n●●●○○\n\n●●○○○\n\n●●○○○\n\n●●○○○\n\n○○○○○\n\n●○○○○\n\n●○○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\n○○○○○\n\nBlood Potency ●○○○○ ○○○○○ Blood Surge Mend Amount Add 2 dice 1 point Superficial Power Bonus Rouse Re-Roll None Level 1 Feeding Penalty Bane Severity No Effect 2 Total Experience Spent Experience True age Apparent age Date of birth Date of death Appearance 1970 2017 Distinguishing features History Daniella sought the truth for years, but she never expected the truth to find her. Her studies on modern-day occult practices attracted the attention of one of the Tremere, a clan whose members are dedicated to mastery over the Blood. She accepted her sireʼs invitation into the night, an invitation her sireʼs superiors didnʼt approve of. Not long after she rose from the dead, agents of the Camarilla destroyed her sire, shifting the Blood inside her into something unrecognizable. From her childhood home, she plans for some payback.\n\nHer invitation to the Anarch gathering arrives as a stray card in her tarot deck. It doesnʼt say much, just the name of her sireʼs murderer and the meetup location.\n\n© 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nSoft-Hearted Detective Bagger Floyd “Sherlock” Benson Name Concept Predator The Primogen's Gambit Malkavian Solve my mortal selfʼs last case Chronicle Ambition Clan 13th Sire Desire Generation ATTRIBUTES Physical Social Mental Strength Charisma Intelligence ●●○○○ ●●○○○ ●●●○○ Dexterity Manipulation Wits ●●○○○ ●●○○○ ●●●●○ Stamina Composure Resolve ●○○○○ ●●○○○ ●●●○○ Health Willpower □□□□■ ■■■■■ □□□□□ ■■■■■ SKILLS Athletics ●●○○○ Animal Ken ●○○○○ Academics ○○○○○ Brawl ○○○○○ Etiquette ○○○○○ Awareness ●●●○○ Craft ○○○○○ Insight ●●○○○ Finance ○○○○○ Drive ○○○○○ Intimidation ●●○○○ Investigation ●●●●○ Firearms Quick Draw ●○○○○ Leadership ○○○○○ Medicine ○○○○○ Melee ○○○○○ Performance ○○○○○ Occult ○○○○○ Larceny Lock-Picking ●○○○○ Persuasion ●●●○○ Politics ○○○○○ Stealth ●●●○○ Streetwise ○○○○○ Science ○○○○○ Survival ○○○○○ Subterfuge ○○○○○ Technology ○○○○○ DISCIPLINES Auspex Obfuscate ●○○○○ ●●●○○ ○○○○○ Heightened Senses Cloak of Shadows Unseen Passage Mask of a Thousand Faces ○○○○○ ○○○○○ ○○○○○ © 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nChronicle Tenets Touchstones & Convictions Clan Bane Sometimes doing the right thing gets people hurt — Penny Gutierrez, his childhood best friend.\n\nWhen the Malkavian suffers a Bestial Failure or a Compulsion, their curse comes to the fore. Suffer a penalty equal to your characterʼs Bane Severity to one category of dice pools (Physical, Social, or Mental) for the entire scene. This is in addition to any penalties incurred by Compulsions.\n\nAdvantages & Flaws\n\nContacts (Mary Ros, fellow P.I.)\n\n●●○○○\n\nIron Gullet\n\n○○○○○\n\nResources\n\n●●○○○\n\nHaven (Benson Investigations Office: Small Size, ●●●○○ — Location, Postern)\n\n○○○○○\n\n○○○○○\n\n-Enemy (Scott Ross, phlebotomist)\n\n●●○○○\n\n-Folkloric Bane: Ultraviolet Light ●○○○○ -Folkloric Block: Garlic ●○○○○ ○○○○○ ○○○○○ Notes Blood Potency ●○○○○ ○○○○○ Blood Surge Mend Amount Add 2 dice 1 point Superficial Power Bonus Rouse Re-Roll None Level 1 Feeding Penalty Bane Severity No Effect 2 Total Experience Spent Experience True age Apparent age Date of birth Date of death Appearance 1986 2021 Distinguishing features History Floydʼs old friends would describe him as “unlucky,” and while he never agreed with them then, now he thinks they might have a point. His love for untangling complex problems brought him into the private detective business, and getting too close to the kidnapper in a missing personʼs case brought him into the Kindred. His looks took a turn for the worse, but heʼs still a keen investigator with a deep sense of empathy. How long will that last?\n\nHis invitation to the Anarch gathering was slipped under the door of his office at Benson Investigations, disguised as a blood toxicity report. Except the details in the report match those of his missing person, and he hasnʼt had a lead on that case in months.\n\n© 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nRugged Survivalist Alleycat Harris “Tick” Porter Name Concept Predator The Primogen's Gambit Carve out a safe home Gangrel Chronicle Ambition Clan 13th Sire Desire Generation ATTRIBUTES Physical Social Mental Strength Charisma Intelligence ●●○○○ ●○○○○ ●●○○○ Dexterity Manipulation Wits ●●●○○ ●●○○○ ●●●○○ Stamina Composure Resolve ●●●●○ ●●○○○ ●●○○○ Health Willpower □□□□□ □□□■■ □□□□■ ■■■■■ SKILLS Athletics ●●●○○ Animal Ken ●●○○○ Academics ○○○○○ Brawl Grappling ●●○○○ Etiquette ○○○○○ Awareness ○○○○○ Craft ○○○○○ Insight ●●●○○ Finance ○○○○○ Drive ○○○○○ Intimidation ○○○○○ Investigation ○○○○○ Firearms ○○○○○ Leadership ○○○○○ Medicine ●○○○○ Melee ●●●○○ Performance ○○○○○ Occult ○○○○○ Larceny ●○○○○ Persuasion ○○○○○ Politics ○○○○○ Stealth ●●○○○ Streetwise Urban Survival ●○○○○ Science ○○○○○ Survival ●●●●○ Subterfuge ○○○○○ Technology ○○○○○ DISCIPLINES Fortitude Potence Protean ●○○○○ ●○○○○ ●●○○○ Resilience Lethal Body Eyes of the Beast Feral Weapons ○○○○○ ○○○○○ ○○○○○ © 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nChronicle Tenets Touchstones & Convictions Clan Bane None may control me — Sally Ward, forest ranger Bloodhound Advantages & Flaws ○○○○○ Contacts (Gang: The Westside Kings)\n\n●●●○○\n\nHaven (The Cabin: Good Size, Postern, Surgery) ●●●●○ Resources ●●○○○ ○○○○○ -Obvious Predator ○○○○○ ○○○○○ ○○○○○ ○○○○○ ○○○○○ ○○○○○ Notes Blood Potency ●○○○○ ○○○○○ Blood Surge Mend Amount Add 2 dice 1 point Superficial Power Bonus Rouse Re-Roll None Level 1 Feeding Penalty Bane Severity No Effect 2 Total Experience Spent Experience True age Apparent age Date of birth Date of death Appearance 1993 2018 Distinguishing features History Harris grew up in the city and wanted to get as far away from it as they could when they came of age. They built a decent life in a forest cabin, only going into the city twice a month for anything nature couldnʼt provide. It was a nighttime supply run that brought them the Embrace: someone hunted them like theyʼd hunt deer. They donʼt know who did it to them, and theyʼd love to find them and give ʻem a piece of their mind. Their invitation to the Anarch gathering wa0s tucked under their truckʼs windshield wiper on their last run to the city: a political mailer about anti-deforestation protests, with the address info crossed out and replaced with the location of the secret meeting. They might have thrown it out just the same, but the Camarilla insignia scrawled across the back gets their attention.\n\n© 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nCharming Impresario Osiris Lorenzo “Swan” Sykes Name Concept Predator The Primogen's Gambit Toreador Establish a media empire.\n\nChronicle Ambition Clan\n\n12th\n\nSire Desire Generation\n\nATTRIBUTES\n\nPhysical Social Mental Strength Charisma Intelligence ●●○○○ ●●○○○ ●●○○○ Dexterity Manipulation Wits ●○○○○ ●●●●○ ●●●○○ Stamina Composure Resolve ●●○○○ ●●○○○ ●●●○○ Health Willpower □□□□□ ■■■■■ □□□□□ ■■■■■ SKILLS Athletics Climbing ●○○○○ Animal Ken ○○○○○ Academics ○○○○○ Brawl ○○○○○ Etiquette ●●●○○ Awareness ○○○○○ Craft ○○○○○ Insight ○○○○○ Finance ●○○○○ Drive ○○○○○ Intimidation ○○○○○ Investigation ○○○○○ Firearms ○○○○○ Leadership ●●●●○ Medicine ○○○○○ Melee ●●○○○ Performance Piano ●●○○○ Occult ○○○○○ Larceny ○○○○○ Persuasion ●●●○○ Politics ○○○○○ Stealth ●○○○○ Streetwise ●●●○○ Science ○○○○○ Survival ○○○○○ Subterfuge ●●○○○ Technology ○○○○○ DISCIPLINES Auspex Presence ●○○○○ ●●●○○ ○○○○○ Heightened Senses Awe Lingering Kiss Entrancement ○○○○○ ○○○○○ ○○○○○ © 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\nChronicle Tenets Touchstones & Convictions Clan Bane An action isnʼt evil so long as the intention is good — Fred “Stump” Davis, washed-up country musician.\n\nWhile your character finds themself in less than beautiful surroundings, lose the equivalent of their Bane Severity in dice from dice pools to use Disciplines.\n\nFame\n\nAdvantages & Flaws\n\nHerd\n\nResources\n\nHaven (Sykes Sound Studios: Good Size, — Luxury, Location)\n\n-Enemies (Preston \"DJ Jeff\" Jefferies, — would-be murderer)\n\n-Disliked (Other music producers)\n\nStigmata\n\nKnown Corpse\n\nNotes\n\n●○○○○\n\n●●○○○\n\n●●○○○\n\n●●●●○\n\n○○○○○\n\n○○○○○\n\n●○○○○\n\n○○○○○\n\n●○○○○\n\n○○○○○\n\n○○○○○\n\nBlood Potency ●○○○○ ○○○○○ Blood Surge Mend Amount Add 2 dice 1 point Superficial Power Bonus Rouse Re-Roll None Level 1 Feeding Penalty Bane Severity No Effect 2 Total Experience Spent Experience True age Apparent age Date of birth Date of death Appearance 1983 2019 Distinguishing features History Lorenzo never had a head for creating music. Their true talent lay in finding those that could and making them stars. As a manager, they brought 2 rock bands, 4 pop stars, 3 emcees, and a DJ with them to fame and fortune. Their meteoric rise as a producer came to a halt when a rival producer shot them after a concert. An Anarch Toreador who ran in the same scene offered a dying Lorenzo the Embrace. Theyʼre still getting their head around the specifics of vampire politics, but the Kindred feel awfully familiar. Their invitation to the Anarch gathering came as a cassette: Stump Davis, live at the Blue Moon. “Live” is crossed out, and the only thing on the tape is someone reading the location for the meeting.\n\n© 2023 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)\n\n© 2022 Renegade Game Studios. All Rights Reserved. © Paradox Interactive AB (publ)", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-three-adaptations.ttrpg", "form": "DEF", "guidance": [], "id": "#v6yAoL9OkD6Vvr8dFbljFfL", "key": "A Toreador “Angel” named Michael?", "name": "A Toreador “Angel” named Michael?", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vAFT30HHVFFGaXECKrPiA67": {"aliases": null, "book": "primogens-gambit", "children": ["#vjkFSKry0usPpqaoeTnxr5K", "#v2mPLOr7KPvwTzBn9gOCy3A", "#vivWeMRufO7NiywXcZu3Do1"], "choices": [], "desc": "Players might want to use the time before the Camarilla meeting to prepare to infiltrate it and enact their plans against Archangel. If this story takes place over two nights, they have the rest of the first night. If this story is one night long, they have at most two hours before the Camarilla meeting begins. Any action with no stated length of time is determined by Storyteller discretion.\n\nCaptain informs the characters that entering the Waterfall Parlor on the night of the meeting requires an invitation, in the form of a gold business card (at least, it does if they’re entering through the front door). If any characters have been captured, she has a hunch that Archangel’s the type to bring them to Elysium so he can humiliate them, in addition to whatever ultimate punishment he has planned.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "form": "DEF", "guidance": [], "id": "#vAFT30HHVFFGaXECKrPiA67", "key": "Arranging Preparations", "name": "Arranging Preparations", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vD12wS57U3YFJQK25r2b10Y": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#vD12wS57U3YFJQK25r2b10Y", "key": "Appendix One: Allies & Antagonists", "name": "Appendix One: Allies & Antagonists", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vDIKp4PAdT13Hj5bxo5HAFG": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Harris grew up in the city and wanted to get as far away from it as they could when they came of age. They built a decent life in a forest cabin, only going into the city twice a month for anything nature couldn’t provide. It was a nighttime supply run that brought them the Embrace: someone hunted them like they’d hunt deer. They don’t know who did it to them, and they’d love to find them and give ‘em a piece of their mind. Their invitation to the Anarch gathering was tucked under their truck’s windshield wiper on their last run to the city: a political mailer about anti-deforestation protests, with the address info crossed out and replaced with the location of the secret meeting. They might have thrown it out just the same, but the Camarilla insignia scrawled across the back gets their attention.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "form": "DEF", "guidance": [], "id": "#vDIKp4PAdT13Hj5bxo5HAFG", "key": "Harris “Tick” Porter (Rugged Survivalist)", "name": "Harris “Tick” Porter (Rugged Survivalist)", "parent": null, "props": [{"name": "Clan", "type": "STRING", "value": "Gangrel", "vk": "scalar"}, {"name": "Embraced", "type": "STRING", "value": "2018 (Born 1993)", "vk": "scalar"}, {"name": "Ambition", "type": "STRING", "value": "Carve out a safe home for me and mine.", "vk": "scalar"}, {"name": "Predator", "type": "STRING", "value": "Alleycat", "vk": "scalar"}, {"name": "Convictions", "type": "STRING", "value": "None may control me.", "vk": "scalar"}, {"name": "Touchstones", "type": "STRING", "value": "Sally Ward, forest ranger.", "vk": "scalar"}, {"name": "Humanity", "type": "STRING", "value": "6", "vk": "scalar"}, {"name": "Generation", "type": "STRING", "value": "13th", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "1", "vk": "scalar"}, {"name": "Attributes", "type": "STRING", "value": "Strength 2, Dexterity 3, Stamina 4; Charisma 1, Manipulation 2, Composure 2; Intelligence 2, Wits 3, Resolve 2", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 8, Willpower 4", "vk": "scalar"}, {"name": "Skills", "type": "STRING", "value": "Athletics 3, Brawl (Grappling) 2, Larceny 1, Melee 3, Stealth 2, Survival 4, Animal Ken 2, Insight 3, Streetwise (Urban Survival) 1, Medicine 1", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Protean 2 (Eyes of the Beast, Feral Weapons), Fortitude 1 (Resilience), Potence 1 (Lethal Body)", "vk": "scalar"}, {"name": "Advantages", "type": "STRING", "value": "Bloodhound, Contacts (Gang: The Westside Kings) 3, Haven (The Cabin: Good Size, Postern, Surgery) 4, Resources 2", "vk": "scalar"}, {"name": "Flaws", "type": "STRING", "value": "Obvious Predator", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vDjho3Auz2CDbAFpGHbCdZ0": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "When the characters follow the address to the Blue Moon, read out or paraphrase: *The Blue Moon is a bar tucked between an alleyway and a long-closed fabric shop. If it wasn’t for the half-functioning neon light depicting a smiling blue crescent rising over the horizon, you’d never know if you’ve made it to the right place.*\n\n*From outside, you hear sub-par electronic music blasting from tinny speakers and raucous laughter. It’s hard to tell through the frosted glass, but it looks like the place is packed, despite its appearance. Two old white men are sitting at a table outside the bar. They’re having a smoke and taking in the night air. They acknowledge you for a moment, holding back grins.*\n\n*There’s a closed-circuit TV camera above the bar entrance and at the basement entrance around back in the alley. One way or another, you’re going to need to find a way into the basement.*\n\n*What do you do?*\n\nThere’s two ways into the Basement. The quietest way is through the back (*The Lock Outside*), but a bold coterie could try heading into the bar (*The Crowd Inside*) and getting into the basement through the backrooms. The coterie may decide to split up according to their strengths and flaws here, with those less adept at social infiltration (Obvious Predators, Known Corpses, or Nosferatu) heading into the alley while Kindred with Looks and Presence go directly to the bar.\n\nRegardless of which way the coterie enters the Blue Moon, there are security cameras to contend with if they want to maximize their time finding evidence in the basement or avoid being tracked down by Archangel in the future. The security camera feeds are displayed on Adriana’s phone, and since it’s a new system, she’s not exactly in the habit of checking it as often as she should.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-one-the-blue-moon.ttrpg", "form": "DEF", "guidance": [], "id": "#vDjho3Auz2CDbAFpGHbCdZ0", "key": "Chapter One: The Blue Moon", "name": "Chapter One: The Blue Moon", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vF9hcCMAwKiXhj2ZRmvQkPG": {"aliases": null, "book": "primogens-gambit", "children": ["#vzA3AqVJWVST52rzJrWZ5bX", "#ve7XSb5kZ4OdQJGPHfHncWI"], "choices": [], "desc": "The Anarchs were the Camarilla’s loyal opposition for almost a century. When the Ivory Tower decided to throw them under a bus with the advent of the Second Inquisition, the city’s Camarilla followed suit, and things soured from there. They quickly established a council of the best and brightest to serve as the first among equals. That the “first among equals” can just draft a bunch of vampires to do their dirty work goes without saying.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#vF9hcCMAwKiXhj2ZRmvQkPG", "key": "The Local Anarchs", "name": "The Local Anarchs", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vFs2tu8Gcwz4IsZJ07brvVv": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "*There’s an empty seat among the local Camarilla’s top vampires, and an up-and-coming lick’ll do anything to take it for himself. He and his allies envision a future for the city, one that has a very bloody end for its Anarchs (read: you). Can you take him down in his own Elysium?*\n\n*The Primogen’s Gambit* is a story for **Vampire: The Masquerade**. It is best suited for a coterie of about threeto-four fledgling Anarch vampires, although it works with up to six and can be adjusted for a Camarilla coterie (see *Appendix Three*, p. 33). The story is designed as either a one-shot, or a story to kick off a **Vampire** chronicle. It can take place over two rough nights, or one of the many long nights of the coterie’s unlife.\n\nSuggestions for speeding up progression or extending playtime are included throughout the story, but the Storyteller can shorten play by converting the Prologue to a flashback and zooming out most of Chapter Three. Adding complications in Chapters One or Three can extend play without being likely to derail the story, while complications added to Chapter Four need to be more closely managed.\n\nThe following summary can be used by Storytellers or event organizers to advertise the game session (such as in event books, flyers, or social media posts) or discussed at the beginning of a game session to check-in with players about the content of the story to be played.\n\n*The coterie is summoned by the local Anarchs to investigate Archangel, a likely candidate to replace the city’s missing Primogen despite his youth and inexperience, and his illicit blood trafficking business. Players’ characters will have to infiltrate a local dive bar to get dirt on Archangel (and get out without getting captured by his loyal ghoul or Kindred security guards), make a plan, and find time to hunt or otherwise appease their Hunger before they risk their necks again by sneaking into Archangel’s jazz club — which also happens to serve as Elysium for the city’s Camarilla.*\n\n*Complications, including connections to the characters’ own backstories and Archangel’s secret involvement with the FBI, should have the characters as invested in Archangel’s demise as the head of the Anarchs herself, if not more so. Can they convince the Court to bring Archangel to justice? Or will they risk everything, going out in a blaze of glory, in order to do so themselves?*\n\nThough the story presents a sketch of a Camarilla Court and an Anarch structure in a generic American metropolitan area, it can take place wherever you set your chronicle. It just needs an empty spot on your city’s Primogen, some kind of tense peace between the Camarilla and Anarchs in the area, and Brenton “Archangel” Finlay and his Midnight Angels (see *Appendix One*) in some form. Modify them as necessary for your setting.\n\nIf the players don’t have time to make their own characters for this story or for convention play, we’ve provided a coterie of six ready-to-play vampires in *Appendix Two: Player Character Coterie*:\n\nimpresario; and\n\nWe recommend starting all characters at 2 Hunger — 3 if they have a flaw or bane that makes hunting more difficult (for example: the Obvious Predator Flaw or the Ventrue clan bane), or 1 if they have traits that make it easier to feed (such as the Herd Background).", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-primogen-s-gambit.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#vFs2tu8Gcwz4IsZJ07brvVv", "name": "The Primogen’s Gambit"}], "id": "#vpgbgjP2bQE8ukPwFrtk641", "name": "Mature Content Warning", "text": "Vampire: The Masquerade addresses the darkness of the world through horror stories. This story contains in-world references and expressions of violence, torture, physical and mental abuse, human trafficking, and death. Groups may also want to downplay references to drugs, alcohol, and specific injuries as needed. Further tools for navigating difficult material are presented in Appendix III: Advice for Considerate Play (Vampire, p. 421).", "topics": []}], "id": "#vFs2tu8Gcwz4IsZJ07brvVv", "key": "The Primogen’s Gambit", "name": "The Primogen’s Gambit", "parent": null, "props": [{"items": [{"value": "Ben “Freebird” Irwin, a zealous Brujah reformer;", "vk": "scalar"}, {"value": "Daniella “Ley Line” Newton, a vengeful Caitiff occultist;", "vk": "scalar"}, {"value": "Harris “Tick” Porter, a rugged Gangrel survivalist;", "vk": "scalar"}, {"value": "Floyd “Sherlock” Benson, a soft-hearted Malkavian detective;", "vk": "scalar"}, {"value": "Lorenzo “Swan” Sykes, a charming Toreador", "vk": "scalar"}, {"value": "Aliyah “Princess” Shaw, a domineering Ventrue opportunist. They’re all fledgling Anarch vampires, each with their own reasons to make the Camarilla’s unlife hell. For a one-shot Story for convention play, the city should be where the game is being played.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vGqssn8r9cEVGpLwCfUcL9I": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "While *The Primogen’s Gambit* may be played by any group looking for an introduction to an Anarch chronicle or a standalone story, the following pages give players character options for those who don’t have prepared characters and want to jump right into playing the game.\n\nAs a newly formed Coterie of fledglings, they’ve yet to develop a specific type (*Vampire: The Masquerade*, pp. 197), but after this story, they could become a type like Marechal, Questari, or Watchmen. A coterie attempting to take over Archangel’s operation in his absence could function as a Hunting Party, or their entrepreneurship could draw the attention and favor of Ministry vampires (*Player’s Guide***,** p. 33).", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "form": "DEF", "guidance": [], "id": "#vGqssn8r9cEVGpLwCfUcL9I", "key": "Appendix Two: Player Character Coterie", "name": "Appendix Two: Player Character Coterie", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vHJzn6fgiCieJFIFJPolMaW": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Here’s the mess the coterie’s about to land itself in.\n\n**Archangel** is the leader of a powerful coterie, the **Midnight Angels**. To further entrench his power, he’s secretly establishing himself within the Circulatory System, a human trafficking network that supplies blood from captive mortals to domains all over the world. While other points of the **Circulatory System** usually keep their vessels in a single location and bring the Kindred to them, Archangel’s an entrepreneur. He’s reached out to some thin-blooded alchemists desperate for the Camarilla’s protection and connections and set up a deal. They are attempting to make him substances that turn bagged blood into edible blood for vampires, allowing him to ship the blood of his captives to anywhere in the world, and he’ll pull some strings to get them out of the Anarchs and into the Camarilla. They don’t know he can’t hold up his end of the bargain, but he’s starting to catch on that they can’t do what they promised, either; all their alchemical efforts have failed so far. And with mounting pressure from his clients, plus the awful things their experiments are leaving in his basement, the thinbloods are more of a liability than asset at this point, one more mess for him to clean up.\n\nThe Circulatory System itself isn’t morally offensive to the city’s Camarilla as a whole, but he’s responsible for several high-profile missing persons cases in the city; beyond the unavoidable difficulties all startups face (accidental deaths, a few escaped victims who remember more than they should), his ghoul has chosen some poor targets, ones who will be missed and maybe avenged. It’s not just a blow to his image as a “moral vampire,” but a genuine threat to the Masquerade. The Prince’s laws also specifically forbid true Kindred from associating with their thin-blooded peers.\n\nArchangel is aware of all this and has a three-point plan to save his skin. The first is to get on the Primogen council. He knows he deserves to be there, and it gets him close enough to the upper echelons of power to enact the second phase: he’ll pin the disappearances on the Anarchs and encourage Sheriff Paul Campana and his hounds to start a purge. He’ll use his position as Primogen to push for the acceptance of thin-blooded into the city’s Camarilla, making him look magnanimous and ensuring his operation’s stability.\n\nThe third phase keeps the mortal investigators at bay: he’s reaching out to organized vampire-hunting groups under an alias. What the Camarilla starts, the forces of the Second Inquisition will finish. All of this is kept in the basement of the Blue Moon and under the watchful eye of Adriana Rollins, both of which are his latest acquisitions. Everything was going well until one of his subordinates caught Snap lurking around the bar. In a panic, he improved the bar’s security and incited his coterie to attack the Anarchs.\n\nSpeaking to the thin-blooded could be dismissed as a *faux pas* (though taking them hostage or disposing of them would be another story), but the sloppiness of his human-trafficking operation would keep Archangel out of power, and his dabbling in thin-blood alchemy could provoke the wrath of Kindred elders. Talking to vampire hunters, even to strike at the Camarilla’s enemies, is enough to get him to face the sun. He’ll still take a risk and make a formal proposal to be the Primogen of the West Side. He’s convinced that the attacks have scared the Anarchs off the trail and that it’s all smooth sailing from here. He’s about to learn he’s dead wrong.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-prologue-crew-expendable.ttrpg", "form": "DEF", "guidance": [], "id": "#vHJzn6fgiCieJFIFJPolMaW", "key": "Behind The Curtain", "name": "Behind The Curtain", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vKH2yWMDJrQdYj7OFAQ9AAR": {"aliases": null, "book": "primogens-gambit", "children": ["#vhnYWCRRcfrKWdtV8LA859L", "#vp6ZGwtmyNyGiawes8nzis6"], "choices": [], "desc": "appropriate, Adriana heads into the basement and Chapter Two begins. Read out or paraphrase: *Before you gather anything more, the basement door slams open above you. Four people run down the stairs, one older woman and three young men. One man carries a machete, another a pistol, and the last a knife.*\n\n*The woman leading the pack has a shotgun. “I think you’ve seen enough,” she says.*\n\n*Some of the men smile, exposing their fangs. No need for the Masquerade in a room like this. Maybe you can still talk your way out of this, or try to escape. But if you’re itching for a fight, they all seem ready to oblige.*\n\n*What do you do?*\n\nAdriana has found the coterie and she’s brought company. They’ve prepared for an intrusion over the past few days, but they weren’t expecting one so soon. At minimum, the coterie can expect a round of Social Combat, but depending on how they open the interaction, they might be able to avoid Physical Combat altogether. If you’re short on time, limit the coterie to one attempt at defusing hostilities; if the coterie rolls a bestial failure in their attempts to lie or deescalate the situation, you can choose to proceed directly to *Physical Combat*.\n\nappropriate.\n\nIf characters attempt to escape or immediately turn to physical violence, proceed directly to *Physical Conflict* (p. 17). Adriana’s vampire backup uses the Anarch\n\nRevolutionary antagonist template (*Vampire*, p. 374), with Health and Willpower reduced to 5. A modified example is provided in *Appendix One* (p. 27) under Midnight Angels. If Adriana is accompanied by ghouls instead of Kindred, they have stats similar to her own; any victims accompanying her should be treated as unfit for combat.\n\nWhen the conflict’s over, go to **Chapter Three**.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-two-busted.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#vKH2yWMDJrQdYj7OFAQ9AAR", "name": "Chapter Two: Busted!"}], "id": "#vDHHruJbadpV6tMFYmspziZ", "name": "Rewarding Clever Plans", "text": "If the characters made plans that could reasonably preclude the intervention of security, such as distracting Adriana or the Kindred at the bar, or if their margins of success or number of criticals argues for a mechanical reward, the Storyteller can adjust who shows up in the basement. Modify the read-aloud text as needed to have Adriana stumble in alone or flanked by ghouls instead of Kindred, or introduce a single Kindred with a new victim, or some other combination of threat that feels narratively", "topics": []}], "id": "#vKH2yWMDJrQdYj7OFAQ9AAR", "key": "Chapter Two: Busted!", "name": "Chapter Two: Busted!", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vNTSNkyXFZgEb8Rf7wJgmjc": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "If one or more members of the coterie were captured, take this opportunity to run a small scene after the other players have had a chance to prepare for the next chapter. Read or paraphrase:\n\n*They didn’t have to throw you in the room with the corpses, but they did.*\n\n*They didn’t bother tying you up or restraining you any further than they already have, which might feel like an insult.*\n\n*The door opens, and a white man steps inside. He’s not too tall or too short, but his shoulders are broad, and his jaw could cut glass. His long, blond hair is perfect.*\n\n*He tosses a bag of blood at you. From the looks of it, this bag’s fresh from the tap.*\n\n*“On the house,” he says with a smile. “Let it never be said I don’t provide hospitality to Anarchs.”*\n\n*His smile melts into a grimace. “I’m Archangel. Who are you?”*\n\n*What do you do?*\n\nArchangel takes the opportunity to interrogate his captives. Through the interrogation, he casually drops elements of his plan if the characters ask about it. He says that he respects the characters for doing this much only on the Anarchs’ orders, noting that they could have been “a fine member of the Camarilla, in better circumstances.”\n\nWhen he’s satisfied with the characters’ answers, or if they’ve put up such a fuss that he gets angry, he says that they’ll get to see Elysium tomorrow night — because he’ll request the Prince condemn them to death there, using his authority as the new Primogen. He takes a moment to enjoy the character’s reaction, if any, before staking them through the heart.\n\nKeep this scene quick, ideally right before **Chapter**", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "form": "DEF", "guidance": [], "id": "#vNTSNkyXFZgEb8Rf7wJgmjc", "key": "Captured Kindred", "name": "Captured Kindred", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vOQbLkwCfSVa0lIarjCFdJx": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-prologue-crew-expendable.ttrpg", "form": "DEF", "guidance": [], "id": "#vOQbLkwCfSVa0lIarjCFdJx", "key": "TABLE 1: CHARACTER MOTIVATIONS", "name": "TABLE 1: CHARACTER MOTIVATIONS", "parent": "#v6Eb692gof3fSrTZ7XBEr4n", "props": [], "refs": [], "slot": null, "table": {"columns": ["CHARACTER", "REWARD", "THREAT"], "rows": [["Zealous Reformer", "You’re eager to tear down an exploitative system…", "…especially if the bastard running it targets your herd."], ["Vengeful Occultist", "You’re out for revenge against the Camarilla for destroying your sire…", "…and Archangel knows your Dark Secret. You need to silence him before he can use that against you."], ["Rugged Survivalist", "Some guarantee of protection would go a long way towards mak ing your Haven a proper home…", "…and Archangel’s entrepreneurial plans are a threat to the undeveloped area outside the city."], ["Soft-Hearted Detective", "Investigating Archangel could also bring you closer to solving your last case as a mortal…", "…and as a Bagger, Archangel’s operation risks tainting your supply, as well as your humanity."], ["Charming Impresario", "With Archangel gone, the Waterfall Parlor would be a nice acquisi tion…", "…and since the Blue Moon is where your Touchstone spends his days, you can’t abide the risk Archangel pos es. Stump can’t keep himself out of trouble, so it’s on you to remove the threat while you still can."], ["Domineering Opportunist", "Defeat for Archangel would be an opportunity for your own ad vancement…", "…and his plans for the city Camarilla are disgustingly favorable to your sire and Adversary. You’re tired of running, and anyone helping your sire track you down is fair game."]]}, "type": "Table", "typeHash": "#vtm5Table000000000001"}, "#vPgO94V6P9Ip8zsRYd5ilph": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Clinging of the Insect", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "form": "DEF", "guidance": [], "id": "#vPgO94V6P9Ip8zsRYd5ilph", "key": "Blood Sorcery Rituals", "name": "Blood Sorcery Rituals", "parent": "#vkRaOAwdTlR1ocYpki9xymB", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vPmk13eSwQOaw00uqmOQSWz": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "In the final chapter, the coterie must make their case against Archangel to the Camarilla, using the evidence they’ve gathered in the basement. *Following Up* (p. 19) details how the coterie gains information based on any photographs taken. The following table can be used to keep track of what they have (and might lose in **Chapter Two** if the engage in a physical conflict) and what approach they might take in **Chapter Five** based on the strength of their case.\n\nIf they manage to take Adriana’s phone, what they find (if they can get access, using some combination of social or technological manipulation) is up to the Storyteller’s discretion, but this should be a big “get” for the coterie. In a longer chronicle, this is a good place to store leads for further stories, but for one-shot play, the phone should contain some kind of combination of information available from the other evidence above and act as a +2 weapon in Chapter Five.\n\nUse of remembered names and information from lost evidence, captured victims, or other complicating elements are subject to the Storyteller’s discretion; if you have additional time, tracking down these leads (possibly at the cost of forgoing Hunting or other preparation in Chapter Three) could result in equivalent evidence to that derived from photos, or additional evidence such as testimony. Alternatively, if you’re pressed for time, the Camarilla has no reason to take the coterie at their word, so while they might follow up on any names or information later on, such evidence doesn’t count towards the coterie’s efforts in Chapter Five.\n\nThe Storyteller can decide whether to allow the coterie to capture any victims (or Adriana); to control for time, fragile victims could die in transit, and kidnapping Adriana could draw more unwanted attention from the police (and Captain’s ire along with it).\n\nThe coterie should have enough time to collect at least one piece of evidence. When they have at least one piece of evidence they can use against Archangel, when they’ve reached their action limit, or when it’s dramatically", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-one-the-blue-moon.ttrpg", "form": "DEF", "guidance": [], "id": "#vPmk13eSwQOaw00uqmOQSWz", "key": "Evidence against Archangel", "name": "Evidence against Archangel", "parent": "#vwvCZU6owZbh7ADnB8ZToJW", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vQHQ8WJe1NGQRUjp79UhPyr": {"aliases": null, "book": "primogens-gambit", "children": ["#v5O9hA33y4F9vDCUQjCaicu", "#vUUTqX2XgI5ZDTIGxZcX6fr"], "choices": [], "desc": "The Midnight Angels are a rising coterie in the West Side of the city. Formed by the charisma of a single Toreador, this assortment of subordinate Kindred and ghouls focus on three things: economic advancement that keeps them rich in money and blood, stronger ties with the Camarilla of the greater region, and the extermination of every single Anarch.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#vQHQ8WJe1NGQRUjp79UhPyr", "key": "Midnight Angels", "name": "Midnight Angels", "parent": null, "props": [{"name": "General Difficulty", "type": "STRING", "value": "4 / 3", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "2", "vk": "scalar"}, {"name": "Standard Dice Pools", "type": "STRING", "value": "Physical 5, Social 5, Mental 6", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 6, Willpower 6", "vk": "scalar"}, {"name": "Exceptional Dice Pools", "type": "STRING", "value": "Athletics 7, Brawl 7, Firearms 6, Larceny 7", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Animalism 2, Fortitude 3, Potence 2", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vTuZ5ItcaLtZFNBv5aRyn8E": {"aliases": null, "book": "primogens-gambit", "children": ["#vf1q3fOtdpaCZsRymGViRoW", "#vVMxTa9JtREpd3MOApL767F"], "choices": [], "desc": "The city’s been Camarilla territory since it was just an overgrown trading post. Unlike some other cities of the Ivory Tower, this city keeps its court slim. There’s a Prince, a Sheriff, a Herald, and four Primogen each representing the strongest coterie in the four corners of the city.\n\nA month ago, the West Side Primogen went missing, and her coterie scattered to the winds. The city’s reclusive Prince is ready to seek out replacements.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#vTuZ5ItcaLtZFNBv5aRyn8E", "key": "The City’s Camarilla", "name": "The City’s Camarilla", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vUUTqX2XgI5ZDTIGxZcX6fr": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Adriana believes that she’s the second-in-command of the Midnight Angels, and it’s true to an extent. The ghoul manages the coterie’s daytime affairs and keeps an eye on the blood prison beneath the Blue Moon. But even with the sacrifices she’s made to keep them in the black and the red flowing, Brenton will never see her as a partner, only a tool.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#vUUTqX2XgI5ZDTIGxZcX6fr", "key": "Adriana Rollins", "name": "Adriana Rollins", "parent": "#vQHQ8WJe1NGQRUjp79UhPyr", "props": [{"name": "General Difficulty", "type": "STRING", "value": "3 / 2", "vk": "scalar"}, {"name": "Standard Dice Pools", "type": "STRING", "value": "Physical 4, Social 3, Mental 3", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 3, Willpower 2", "vk": "scalar"}, {"name": "Exceptional Dice Pools", "type": "STRING", "value": "Firearms 4, Stealth 5, Intimidation 6, Awareness 5 Disciplines: Presence 1 (Daunt)", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vUdwLDrkA0lB8lpkEwTweBc": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "For a Camarilla coterie, Captain can be replaced with an existing character within the organization, perhaps someone the characters would appreciate having as a Mawla or someone with other authority to convince them to act against Archangel.\n\nThe “high-profile kidnappings” could provide a good alternate hook for an existing chronicle, one that could easily dispense with the prologue and/or alter the Captain’s role and affiliation to accommodate a Camarilla or other coterie that doesn’t fit the current Anarch setup. A Camarilla coterie could also approach this story from the angle of investigating the disappearance of one of the Primogen and the vampire rumored to be likely to fill that seat.\n\nStorytellers can easily adapt the anonymous invitation the coterie receives in the Prologue, as well as Captain’s promised rewards — or perhaps threats — to integrate the story within an existing chronicle.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-three-adaptations.ttrpg", "form": "DEF", "guidance": [], "id": "#vUdwLDrkA0lB8lpkEwTweBc", "key": "Alternate beginnings", "name": "Alternate beginnings", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vV2YkMq5mBpZBT3WxdLeKzN": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Examining the security cameras at the main entrance and inside the bar is an Intelligence + Technology test, Difficulty 2. A win reveals that they’re top of the line cameras, almost certainly installed after Snap got caught, but they’re also connected to the internet and full of coding exploits; consider rewarding exceptional successes by lowering the Difficulty of the next test or disabling the cameras outright for a set amount of time. Access to proper tools (see *Equipment and Preparedness Tests*) and a Wits + Technology test (Difficulty 3) or a Wits + Larceny test (Difficulty 4) keep the cameras’ eyes off the coterie for the rest of the scene. Winning either test at a cost could draw attention to the characters, requiring them to spend extra time or make additional social skill tests to avoid suspicion; bestial failures or messy criticals could mean more dire complications, possibly with a limited audience to avoid derailing the story before it fully begins.\n\nThe characters can pose as normal patrons and walk into the bar with no issue, but getting in unnoticed without an appropriate use of Obfuscate is more complicated. Sneaking into the bar in this crowd without disabling the security cameras in the building is a Dexterity + Stealth test, Difficulty 5. A good enough distraction, like starting a bar fight, making enough noise to get the crowd to look outside, or clearing out the place with a false fire alarm reduces the Difficulty to 3, but might require other tests at the Storyteller’s discretion. If the cameras are disabled, the test starts at Difficulty 4 but can be reduced to 2 with a sufficient distraction.\n\nThe crowd inside the bar consists of college-aged kids and older office worker types trying to look like college-aged kids. The lighting’s dingy, save for a hastily made dance floor in the center lit by two spotlights. It’s a good place for a drink if the characters are so inclined; the Blue Moon is a Difficulty 2 hunting ground. Table 3: Hunting (p. 21) contains the predator type and likely dice pools for the pre-generated characters, with more detailed information available in *Hunting* (**Vampire,** p. 306). To avoid having failures derail the story, offer narratively appropriate options for winning at a cost, such as requiring a character to spend extra time cleaning up after a messy attempted feeding or getting caught by a territorial Kindred who accuses the character of poaching on their turf. The Storyteller can also introduce consequences that the character has to deal with in the future, such as arousing suspicion in a mortal colleague or incurring Stains that threaten the character’s humanity.\n\nThere are three vampires in the crowd, all with the Blush of Life activated. They’re working for Archangel, but they’re not part of his coterie. They’re working security for the operation in hopes that they’ll get to join and get a fast track to membership in the Camarilla once he’s on the Primogen; they might balk at seeming to take orders from a ghoul like Adriana, but if they want Archangel’s help, they don’t have much choice. Until the coterie starts heading for the basement door, tries to start a distraction, or feeds on crowd members in an unsubtle way, the vampires won’t take notice of them. If the coterie draw attention to themselves, the vampires can detect them with Sense the Beast; test Resolve + Animalism (using the stats for Midnight Angels, p. 27 or just assume 3 successes) against the character’s Composure + Subterfuge (Vampire, p. 245).\n\nAmong the busy bartenders is a frazzled white woman in her late 50s, the oldest person working there. That’s Adriana. Archangel told her to keep an eye out for any suspicious characters. If any member of the coterie has humanity of less than 7 and isn’t using Blush of Life, gets a little too rough on the bar’s patrons, or has a feeding go wrong, they’re in her sights. Otherwise, she’ll treat them like any other guest.\n\nPLAYING MORTAL **The pre-generated characters are all Humanity 6 or 7, so they’ll need to use Blush of Life if they want to have a “normal” drink at the bar without vomiting it up (Vampire, p. 237).**\n\nor Touchstones are out for a drink at the same bar.\n\nIf the coterie knows about the “new management” from the old men and strikes up conversation with Adriana, she brushes off their concerns. She tells the coterie how her business suffered for years until “her guardian angel” came along. She talks about the bar’s new owner, who she calls “Michael,” the way someone might talk about a crush. It’s sweet, but there’s just enough physicality in there that it’s awkward. She says that the two of them are up to some big things but won’t get into the details.\n\nThe door to the basement is behind the bar, which is currently occupied by bartenders and patrons. Most of the customers are too busy drinking and chatting to notice a few people sneaking into the backroom but might call them out because of a failed test. The bartenders are more aware, especially Adriana.\n\nWith the right words and a solid cover story (e.g. being a health inspector, a maintenance worker, or a gig delivery driver), the coterie could convince one of the bartenders to let them in the back. Convincing any of the bartenders to let them in is a Manipulation + Persuasion test at Difficulty 2, but they’ll let Adriana know that the characters are heading into the back without an incentive or Discipline to convince them otherwise. Convincing Adriana to let them in is a test at Difficulty 3 and even then, she’ll want to only let one person in the back, whom she’ll escort. A major bribe (Resources 3 or higher), a successful use of an appropriate Discipline, or convincing her that the coterie is connected to “Michael” lets her relent long enough to give the coterie time to gather evidence in the basement.\n\nAdriana and the bartenders are tough folks, and any test to intimidate them starts at Difficulty 4.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-one-the-blue-moon.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#vV2YkMq5mBpZBT3WxdLeKzN", "name": "The Crowd Inside"}], "id": "#vau2SVBhd0x6W58qV4CgQbs", "name": "The Crowd Inside Sidebar", "text": "Some of the pre-generated characters have a harder time passing for human than others; Kindred with the flaws Obvious Predator as well as those with Known Corpse are at risk of drawing unwanted attention, and the Folkloric Bane against ultraviolet light could come into play when bartenders check IDs with a black light or if the bathroom uses blue light to deter drug use. Even characters without these specific flaws can run into trouble if their Contacts", "topics": []}], "id": "#vV2YkMq5mBpZBT3WxdLeKzN", "key": "The Crowd Inside", "name": "The Crowd Inside", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vVMxTa9JtREpd3MOApL767F": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "When it was clear that he had to choose between his clan and his obligations, Paul chose the latter. The Brujah’s loyalty was rewarded with an appointment to Sheriff, a title he’s held in the years since. He has a grudging respect for the Anarchs for keeping their end of the deal and not causing the city’s cold war to turn hot so far, but that could change very soon. He protects the court, the sanctity of Elysium, and then himself, in that order.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#vVMxTa9JtREpd3MOApL767F", "key": "Paul Campana", "name": "Paul Campana", "parent": "#vTuZ5ItcaLtZFNBv5aRyn8E", "props": [{"name": "General Difficulty", "type": "STRING", "value": "5 / 3", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "2", "vk": "scalar"}, {"name": "Standard Dice Pools", "type": "STRING", "value": "Physical 7, Social 5, Mental 4", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 6, Willpower 5", "vk": "scalar"}, {"name": "Exceptional Dice Pools", "type": "STRING", "value": "Brawl 8, Firearms 6, Melee 6, Intimidation 7", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Celerity 2, Potence 3, Presence 1", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vXEn3eJgxDfztwnGwXULiXu": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "**Four**.\n\nIf this is a new night, remember to have the players make a Rouse Check.\n\nWhen the coterie arrives at the Waterfall Parlor, read or paraphrase:\n\n*The Waterfall Parlor is the Blue Moon’s opposite. It’s a jazz club in the heart of the city, designed with a modern eye for architecture. Tonight, it’s closed off for a “private event.” This is where Archangel will make his bid to join the Primogen council.*\n\n*You see a few people flashing golden business cards to the bouncer, who lets them in. There’ s an employee entrance in the back and a greenroom entrance on the side. A small security detail circles the perimeter.*\n\n*Once you go in, there’s no turning back. Archangel is coming out of that club a disgrace or he’s not coming out of there at all. What do you do?*", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-four-parlor-games.ttrpg", "form": "DEF", "guidance": [], "id": "#vXEn3eJgxDfztwnGwXULiXu", "key": "Chapter Four: Parlor Games", "name": "Chapter Four: Parlor Games", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vYon7x7B7vCiRqtWgtFqA6V": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "The old men outside, Kent and Melvin, are curmudgeons, amused at the coterie’s presence. If the coterie heads into the bar or hangs around outside long enough for them to notice, Kent jokingly wonders if the characters are the “fresh young faces” the new management promised they’d bring.\n\nChatting with the old men reveals that the Blue Moon’s been around for years. They’re regular patrons, the only original regulars left after the previous owner, Adriana (p. 27), sold off “her pride and joy” to “some young blonde tightwad she can’t get enough of.” She’s still working at the bar tonight. The men invite the coterie to head inside if they want to see “a sad old woman try to keep up with the times.”\n\nWith Presence or a Charisma + Persuasion test at Difficulty 2 the coterie could convince the old men to vouch for them when lying to or manipulating Adriana. Using them this way reduces any Difficulty on such tests by 1 a success with a high margin means that Adriana considers the characters about as trustworthy as Kent and Melvin — tests to lie to, charm, or distract her automatically succeed, within reason.\n\nIf the characters are heading in through *The Lock Outside*, they can take this opportunity to build a cover story with the two men, posing as maintenance or delivering supplies; it’s unlikely they’ll fool Adriana in this way, but it could keep bartenders and other mortals from asking questions about their presence.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-one-the-blue-moon.ttrpg", "form": "DEF", "guidance": [], "id": "#vYon7x7B7vCiRqtWgtFqA6V", "key": "The Two Old Men (Optional)", "name": "The Two Old Men (Optional)", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vZDEzOYzbn9vRwp1syD6hHw": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "form": "DEF", "guidance": [], "id": "#vZDEzOYzbn9vRwp1syD6hHw", "key": "TABLE 3: HUNTING STYLES", "name": "TABLE 3: HUNTING STYLES", "parent": "#vivWeMRufO7NiywXcZu3Do1", "props": [], "refs": [], "slot": null, "table": {"columns": ["CHARACTER", "PREDATOR TYPE (POOL)"], "rows": [["Zealous Reformer", "Scene Queen (Local Activists; Manipulation + Persuasion)"], ["Vengeful Occultist", "Cleaver (Manipulation + Subterfuge)"], ["Rugged Survivalist", "Alleycat (Strength + Brawl)"], ["Soft-Hearted Detective", "Bagger (Intelligence + Streetwise)"], ["Charming Impresario", "Osiris (Manipulation + Subterfuge or Intimidation + Fame)"], ["Domineering Opportunist", "Sandman (Dexterity + Stealth)"]]}, "type": "Table", "typeHash": "#vtm5Table000000000001"}, "#vZzfYF1x0fdylriKrDh1HLZ": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Lorenzo never had a head for creating music. Their true talent lay in finding those that could and making them stars. As a manager, they brought two rock bands, four pop stars, three emcees, and a DJ with them on the road to fame and fortune. Their meteoric rise as the person-behind-the-person came to a halt when a rival producer shot them after a concert. An Anarch Toreador who ran in the same scene saw an opportunity and offered a dying Lorenzo the Embrace. They’re still getting their head around the specifics of vampire politics, but the Kindred feel awfully familiar. Their invitation to the Anarch gathering came as an audio recording. Normally someone else handles all the tapes that make their way in from hopeful artists seeking Lorenzo’s representation, but this came as a cassette: Stump Davis, live at the Blue Moon. “Live” is crossed out, and the only thing on the tape itself is someone reading the location for the meeting.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "form": "DEF", "guidance": [], "id": "#vZzfYF1x0fdylriKrDh1HLZ", "key": "Lorenzo “Swan” Sykes (Charming Impresario)", "name": "Lorenzo “Swan” Sykes (Charming Impresario)", "parent": null, "props": [{"name": "Clan", "type": "STRING", "value": "Toreador", "vk": "scalar"}, {"name": "Embraced", "type": "STRING", "value": "2019 (Born 1983)", "vk": "scalar"}, {"name": "Ambition", "type": "STRING", "value": "Establish a media empire.", "vk": "scalar"}, {"name": "Predator", "type": "STRING", "value": "Osiris", "vk": "scalar"}, {"name": "Convictions", "type": "STRING", "value": "An action isn’t evil so long as the intention is good.", "vk": "scalar"}, {"name": "Touchstones", "type": "STRING", "value": "Fred “Stump” Davis, washed-up country musician.", "vk": "scalar"}, {"name": "Humanity", "type": "STRING", "value": "7", "vk": "scalar"}, {"name": "Generation", "type": "STRING", "value": "12th", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "1", "vk": "scalar"}, {"name": "Attributes", "type": "STRING", "value": "Strength 2, Dexterity 1, Stamina 2; Charisma 2, Manipulation 4, Composure 2; Intelligence 2, Wits 3, Resolve 3", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 5, Willpower 5", "vk": "scalar"}, {"name": "Skills", "type": "STRING", "value": "Athletics (Climbing) 1, Melee 2, Stealth 1, Etiquette 3, Leadership 4, Performance (Piano) 2, Persuasion 3, Streetwise 3, Subterfuge 2, Finance 1", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Presence 3 (Awe, Lingering Kiss, Entrancement), Auspex 1 (Heightened Senses)", "vk": "scalar"}, {"name": "Advantages", "type": "STRING", "value": "Fame 1, Herd 2, Resources 3, Haven (Sykes Sound Studios: Good Size, Luxury, Location) 4", "vk": "scalar"}, {"name": "Flaws", "type": "STRING", "value": "Enemies (Preston “DJ Jeff” Jefferies, Would-Be Murderer) 1, Disliked (Other Music Producers) Stigmata, Known Corpse", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vbRq5qd0V8AaoAQZcopYCrU": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Floyd’s old friends would describe him as “unlucky,” and while he never agreed with them then, now he thinks they might have a point. His love for untangling complex problems brought him into the private detective business, and getting too close to the kidnapper in a missing person’s case brought him into the Kindred. His looks took a turn for the worse, but he’s still a keen investigator with a deep sense of empathy. How long will that last? His invitation to the Anarch gathering was slipped under the door of his office at Benson Investigations, disguised as a blood toxicity report. Except the details in the report match those of his missing person, and he hasn’t had a lead on that case in months.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "form": "DEF", "guidance": [], "id": "#vbRq5qd0V8AaoAQZcopYCrU", "key": "Floyd “Sherlock” Benson (Soft-Hearted Detective)", "name": "Floyd “Sherlock” Benson (Soft-Hearted Detective)", "parent": null, "props": [{"name": "Clan", "type": "STRING", "value": "Malkavian", "vk": "scalar"}, {"name": "Embraced", "type": "STRING", "value": "2021 (Born 1986)", "vk": "scalar"}, {"name": "Ambition", "type": "STRING", "value": "Solve my mortal self’s last case.", "vk": "scalar"}, {"name": "Predator", "type": "STRING", "value": "Bagger", "vk": "scalar"}, {"name": "Convictions", "type": "STRING", "value": "Sometimes doing the right thing gets people hurt.", "vk": "scalar"}, {"name": "Touchstones", "type": "STRING", "value": "Penny Gutierrez, his childhood best friend.", "vk": "scalar"}, {"name": "Humanity", "type": "STRING", "value": "7", "vk": "scalar"}, {"name": "Generation", "type": "STRING", "value": "13th", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "1", "vk": "scalar"}, {"name": "Attributes", "type": "STRING", "value": "Strength 2, Dexterity 2, Stamina 1; Charisma 2, Manipulation 2, Composure 2; Intelligence 3, Wits 4, Resolve 3", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 4, Willpower 5", "vk": "scalar"}, {"name": "Skills", "type": "STRING", "value": "Athletics 2, Larceny (Lock-Picking) 1, Firearms (Quick-Draw) 1, Stealth 3, Animal Ken 1, Insight 2, Intimidation 2, Persuasion 3, Awareness 3, Investigation 4", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Obfuscate 3 (Cloak of Shadows, Unseen Passage, Mask of a Thousand Faces), Auspex 1 (Heightened Senses)", "vk": "scalar"}, {"name": "Advantages", "type": "STRING", "value": "Contacts (Mary Ross, fellow PI) 2, Iron Gullet, Resources 2, Haven (Benson Investigations Office: Small Size, Location, Postern) 3", "vk": "scalar"}, {"name": "Flaws", "type": "STRING", "value": "Enemy (Scott Ross, phlebotomist) 2, Folkloric Bane: Ultraviolet Light, Folkloric Block: Garlic", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#ve7XSb5kZ4OdQJGPHfHncWI": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Shanon’s the eyes and ears of the Anarchs. They’re the one who first brought up Brenton’s ambitions to the council. The Nosferatu claims that they’ve been trying to find anything that might thwart those ambitions, but Archangel’s goons have been keeping an eye out for them. They’ll provide the coterie with whatever information they need but would like them to maintain the Masquerade.\n\nGeneral Difficulty: 4 / 2 Blood Potency: 1 Standard Dice Pools: Physical 5, Social 4, Mental 5 Secondary Attributes: Health 4, Willpower 4 Exceptional Dice Pools: Stealth 8, Streetwise 7, Awareness 6, Investigation 5 Disciplines: Animalism 1, Obfuscate 3, Potence 2", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#ve7XSb5kZ4OdQJGPHfHncWI", "key": "Shanon “Snap” Beasley", "name": "Shanon “Snap” Beasley", "parent": "#vF9hcCMAwKiXhj2ZRmvQkPG", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vf1q3fOtdpaCZsRymGViRoW": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Very few Kindred have seen the Prince, but everyone’s seen Avery. As the city’s Herald, they’re the go-between for the Kindred at large and their ruler. They have a near-photographic memory and a head for names, but the Malkavian can’t keep tabs on everyone in the city. They’re suspicious of Brenton’s ambitions but can’t find anything to pin on him.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#vf1q3fOtdpaCZsRymGViRoW", "key": "Avery Vega", "name": "Avery Vega", "parent": "#vTuZ5ItcaLtZFNBv5aRyn8E", "props": [{"name": "General Difficulty", "type": "STRING", "value": "4 / 3", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "2", "vk": "scalar"}, {"name": "Standard Dice Pools", "type": "STRING", "value": "Physical 5, Social 6, Mental 5", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 6, Willpower 6", "vk": "scalar"}, {"name": "Exceptional Dice Pools", "type": "STRING", "value": "Etiquette 7, Insight 6, Streetwise 7, Politics 8", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Auspex 3, Dominate 2, Obfuscate 3", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vgMWTDcSDJsabjj9qo4jAAH": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Alter references to the West Side as appropriate to encompass a relevant neighborhood, district, or the city itself if it’s too small to be feasibly divided among different Primogen.\n\nIf you have a downtown, you have a dive bar, and you probably have a suitably fancy stand-in for the Waterfall Parlor as well. The Anarchs’ meeting in the Herrick’s, the parks and neighborhoods where pre-generated characters have their Havens, and any unspecified secondary locations can be easily adapted to reference their local counterparts, or left as generic grocery stores and offices.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-three-adaptations.ttrpg", "form": "DEF", "guidance": [], "id": "#vgMWTDcSDJsabjj9qo4jAAH", "key": "Adapting the story for your city", "name": "Adapting the story for your city", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vgQih0kDOhsgY0Qq4Dd0HeL": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-one-the-blue-moon.ttrpg", "form": "DEF", "guidance": [], "id": "#vgQih0kDOhsgY0Qq4Dd0HeL", "key": "TABLE 2: EVIDENCE", "name": "TABLE 2: EVIDENCE", "parent": "#vwvCZU6owZbh7ADnB8ZToJW", "props": [], "refs": [], "slot": null, "table": {"columns": ["EVIDENCE (WEAPON)", "USE", "SEVERITY ADD SOMETHING FOR WEAPON CONVERSION"], "rows": [["Pictures of captives or corpses (+1)", "Uncover identities of missing persons in the city", "Archangel’s operation is at least unseemly enough to keep him out of the Primogen, and at worst a Masquerade breach requiring punishment. If characters didn’t discover the presence of a thin-blooded vampire corpse, they could have another opportunity to attempt that test if they have a picture of the corpse, at the Storyteller’s discretion."], ["Pictures of blood bags (+1)", "Labels indicate extensive alchemical experimentation", "His human trafficking is outside the bounds of what the Circulatory System engages in, and his operation is entirely dependent on thin-blooded Anarch alchemists. Whether this constitutes a Masquerade breach or something else dire depends on what characters can learn or prove regarding the identities of the victims and conspirators."], ["Samples of bagged blood or “special sauce” (+1)", "Holds evidence of Archangel’s use of thin-blood alchemists", "As above, this evidence also implicates Archangel in fraternization with the thin-blooded (a minor offense). Plus, word has it the reclusive Prince considers alchemy to be especially distasteful, something akin to watered-down diablerie."], ["Spreadsheet of victims, clients, and coconspirators (+1)", "Reveals the extent and timeline of Archangel’s operations", "At the Storyteller’s discretion, names could be added to the client or conspirator list that implicate other members of the Camarilla or otherwise complicate the use of this evidence for the story, giving characters options ranging from further investigation to outright blackmail. In a longer chronicle, the spreadsheet can provide hooks for future stories."], ["Thin blood corpse (+2)", "Archangel has infringed on the Prince’s right of destruction", "Using this evidence might require the coterie to persuade the Camarilla of what took place, giving a presentation using the projector. The pre-generated characters could use Academics (Teaching) or Medicine to persuade the Camarilla that this could not be a mortal corpse. And someone on the Court using Archangel’s services could have a strong reaction to inadvertently drinking from another Kindred, even a thin-blood."], ["Correspondence with FBI (+2)", "Evidence of clear violation punishable by final death", "If the coterie leaves with this evidence, the more brazen options for confronting Archangel in Chapter Five are much more likely to succeed. The Storyteller can choose to give this evidence additional numerical weight in lowering the Difficulty of associated tests or give it weight through narrative means, such as rewarding characters with Camarilla entry if they succeed."]]}, "type": "Table", "typeHash": "#vtm5Table000000000001"}, "#vh3bx91dcPzgZupqKROyOic": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "From an early age, Ben knew that the world was unfair. He thought he could change the system from the inside as a local politician’s aide, but a bad night and the Embrace of a Camarilla loyalist seeking power over his boss proved the world’s corruption went deeper than he imagined. Free of his sire’s control, he won’t make the same mistake twice.\n\nHis invitation to the Anarch gathering arrives by bike messenger, slipped into a delivery order for his activist housemates. The note scrawled on the receipt mentions information about a local protestor whose disappearance has his Herd worried.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "form": "DEF", "guidance": [], "id": "#vh3bx91dcPzgZupqKROyOic", "key": "Ben “Freebird” Irwin (Zealous Reformer)", "name": "Ben “Freebird” Irwin (Zealous Reformer)", "parent": null, "props": [{"name": "Clan", "type": "STRING", "value": "Brujah", "vk": "scalar"}, {"name": "Embraced", "type": "STRING", "value": "2016 (Born 1996)", "vk": "scalar"}, {"name": "Ambition", "type": "STRING", "value": "Tear down any system that exploits the weak.", "vk": "scalar"}, {"name": "Predator", "type": "STRING", "value": "Scene Queen (Local Activists)", "vk": "scalar"}, {"name": "Convictions", "type": "STRING", "value": "Protect the innocent from harm.", "vk": "scalar"}, {"name": "Touchstones", "type": "STRING", "value": "Alex Lee, long-suffering single father.", "vk": "scalar"}, {"name": "Humanity", "type": "STRING", "value": "7", "vk": "scalar"}, {"name": "Generation", "type": "STRING", "value": "13th", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "1", "vk": "scalar"}, {"name": "Attributes", "type": "STRING", "value": "Strength 3, Dexterity 4, Stamina 3; Charisma 2, Manipulation 2, Composure 1; Intelligence 2, Wits 2, Resolve 2", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 6, Willpower 3", "vk": "scalar"}, {"name": "Skills", "type": "STRING", "value": "Athletics 4, Brawl 3, Driving 3, Melee 2, Intimidation 3, Leadership (Local Activists) 2, Streetwise 2, Academics (Research) 1, Awareness 1, Medicine (First-Aid) 1", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Celerity 2 (Cat’s Grace, Fleetness), Potence 2 (Soaring Leap, Prowess)", "vk": "scalar"}, {"name": "Advantages", "type": "STRING", "value": "Fame (Local Activists) 1, Contact (Local Activists) 1, Haven (Rented House: Good Size, Library) 3, Resources 2, Herd (Local Activists) 2", "vk": "scalar"}, {"name": "Flaws", "type": "STRING", "value": "Disliked (City Government), Known Blankbody", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vhYWWgzYEHkBucDIW70q4UH": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Aliyah’s life and unlife were decided for her. The youngest in a family of Ghouls, the blood-addicted servants of a vampire, her sire hand-picked her for a promotion into undeath. The Camarilla was fun, but any path to greater power was cut off by older vampires of greater stature. When she realized that anyone in the Anarchs could rise to dominance through sheer gumption, she knew what to do. Her sire and her family are pissed, but they’re far away now. Here, Aliya’s the master of her own destiny. Her invitation to the Anarch gathering arrives on Julian Howard’s letterhead. She gets ready to move to a new crash pad, again, but the envelope is empty, a timestamp written on the inside. When she reviews that moment on her home security system footage, the camera is covered, only for an instant, by a piece of paper bearing the details of the Anarch meeting.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "form": "DEF", "guidance": [], "id": "#vhYWWgzYEHkBucDIW70q4UH", "key": "Aliyah “Princess” Shaw (Domineering Opportunist)", "name": "Aliyah “Princess” Shaw (Domineering Opportunist)", "parent": null, "props": [{"name": "Clan", "type": "STRING", "value": "Ventrue", "vk": "scalar"}, {"name": "Embraced", "type": "STRING", "value": "2020 (Born 2002)", "vk": "scalar"}, {"name": "Ambition", "type": "STRING", "value": "Become Baron of this charming little city.", "vk": "scalar"}, {"name": "Predator", "type": "STRING", "value": "Sandman", "vk": "scalar"}, {"name": "Convictions", "type": "STRING", "value": "Always keep your sworn word.", "vk": "scalar"}, {"name": "Touchstones", "type": "STRING", "value": "Rob Watson, distant relative but close friend.", "vk": "scalar"}, {"name": "Humanity", "type": "STRING", "value": "7", "vk": "scalar"}, {"name": "Generation", "type": "STRING", "value": "12th", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "1", "vk": "scalar"}, {"name": "Attributes", "type": "STRING", "value": "Strength 2, Dexterity 2, Stamina 2; Charisma 4, Manipulation 3, Composure 3; Intelligence 1, Wits 2, Resolve 2", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 5, Willpower 5", "vk": "scalar"}, {"name": "Skills", "type": "STRING", "value": "Athletics 2, Driving 1, Firearms 2, Larceny 1, Etiquette 3, Stealth 1 (Break-In), Intimidation 2, Leadership 3, Persuasion 4, Subterfuge 3", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Auspex 1 (Sense the Unseen), Dominate 2 (Compel, Mesmerize), Fortitude 1 (Unswayable Mind)", "vk": "scalar"}, {"name": "Advantages", "type": "STRING", "value": "Looks (Beautiful), Resources 4, Haven 3 (Crash Pad: Small Size, Luxury, Security System)", "vk": "scalar"}, {"name": "Flaws", "type": "STRING", "value": "Adversary (Julian Howard, Sire) 2", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vhnYWCRRcfrKWdtV8LA859L": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Adriana and the Kindred don’t recognize the coterie as Anarchs on sight. The characters can play this to their advantage. Unless they’ve made their ties to the Anarchs clear, they could pass themselves off as independent actors or even Camarilla investigators. This kind of play is a Charisma + Performance or a Manipulation + Subterfuge test at Difficulty 3. A win doesn’t entirely calm their fears, but it opens the door to negotiation. A critical win or a margin of success of at least 4 either throws them off guard and gives the coterie a +1 bonus to dice pools for the coming conflict, or defuses all hostilities entirely at the Storyteller’s discretion. The coterie can still attempt to deescalate or proceed to *Social Conflict,* p. 7.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-two-busted.ttrpg", "form": "DEF", "guidance": [], "id": "#vhnYWCRRcfrKWdtV8LA859L", "key": "Lying", "name": "Lying", "parent": "#vKH2yWMDJrQdYj7OFAQ9AAR", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vivWeMRufO7NiywXcZu3Do1": {"aliases": null, "book": "primogens-gambit", "children": ["#vZDEzOYzbn9vRwp1syD6hHw"], "choices": [], "desc": "The characters can hunt to keep their Hunger at bay for the obstacles ahead or for extra opportunities to heal with the Blood. This is zoomed-out hunting (*Vampire: The Masquerade*, pp. 306–307). A successful hunt either takes half of the rest of the first night, or just enough time to do something short and quick before the meeting begins, depending on story length. Any purloined blood bags from the Blue Moon can, at the Storyteller’s discretion, be used by Baggers either as normal or with ensuing complications from any experiments done on the samples.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "form": "DEF", "guidance": [], "id": "#vivWeMRufO7NiywXcZu3Do1", "key": "Hunting", "name": "Hunting", "parent": "#vAFT30HHVFFGaXECKrPiA67", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vjkFSKry0usPpqaoeTnxr5K": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "In most Camarilla domains, violence is forbidden at Elysium, and bringing the Final Death without the Prince’s sanction is a crime. But Anarchs don’t have to care about what the Camarilla or some Prince says, if they can survive the consequences. If the coterie is (understandably) reluctant to enter Elysium, the Storyteller has several options for convincing them. If you’re running short on time, reminding characters of the threats Archangel poses detailed in Table 1 (p. 8) should do the trick, but in a longer chronicle, consider having characters roleplay this reluctance by contacting Captain or Snap. They might put the coterie in contact with someone who could eventually become a Mentor (Mawla) for guidance on how to act at Elysium, or reassure them that, as long as the coterie doesn’t break the rules of Elysium, their safety is secured.\n\nIf the coterie is expecting or planning to make the meeting go loud, they can acquire weapons and other tools through relevant Advantages. For pre-generated characters, these Advantages include Contacts (activists, gang members, and a private investigator), Resources, and Fame. It’s too late at night and too soon to obtain these things through legal means, but any character with criminal or underground connections should have little problem obtaining firepower. This creates its own challenges in later chapters.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "form": "DEF", "guidance": [], "id": "#vjkFSKry0usPpqaoeTnxr5K", "key": "Lock and Load", "name": "Lock and Load", "parent": "#vAFT30HHVFFGaXECKrPiA67", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vk8cfg1Us6YfaDl3kJtCJsH": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Unwilling to trust the Camarilla’s justice, the coterie captures Archangel and brings him into the Anarchs’ custody.\n\nIf the coterie wants to convince the upper crust to let them take Archangel, one member can make a Charisma + Leadership test at Difficulty 7. Each piece of evidence the coterie has reduces the Difficulty by 1, and the rules for teamwork could apply here. There’s no win with a cost here, it’s all or nothing, so the coterie should consider the strength of their evidence against him. If the coterie has evidence of Archangel’s collaboration with the FBI, for instance, this could help convince the Court to distance themselves from Archangel immediately and allow the Anarchs to do the dirty work.\n\nOn a win, the upper crust is convinced that they should let the Anarchs take care of it. Archangel and his guards threaten a fight but Paul blocks his guards and stakes him. He shoves the captive in the coterie’s direction and demands they leave.\n\nOn a failure, Avery mocks the coterie and lets them know that the Camarilla doesn’t do mob justice. Paul escorts them out, by force if necessary. As they leave, they get to see Archangel demand a seat on the Primogen to a frosty reception. Perhaps a small victory is enough.\n\nIf the coterie decides to capture Archangel without talking, follow the advice in *Killing Archangel* (p. 25), except replace killing Archangel with restraining him and removing him from the VIP room in three rounds.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-five-tumbling-down.ttrpg", "form": "DEF", "guidance": [], "id": "#vk8cfg1Us6YfaDl3kJtCJsH", "key": "Capturing Archangel", "name": "Capturing Archangel", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vkRaOAwdTlR1ocYpki9xymB": {"aliases": null, "book": "primogens-gambit", "children": ["#vPgO94V6P9Ip8zsRYd5ilph"], "choices": [], "desc": "Daniella sought the truth for years, but she never expected the truth to find her. Her studies on modern-day occult practices attracted the attention of one of the Tremere, a clan whose members are dedicated to mastery over the Blood. She accepted her sire’s invitation into the night, an invitation her sire’s superiors didn’t approve of. Not long after she rose from the dead, agents of the Camarilla destroyed her sire, shifting the Blood inside her into something unrecognizable. From her childhood home, she plans for some payback. Her invitation to the Anarch gathering arrives as a stray card in her tarot deck. It doesn’t say much, just the name of her sire’s murderer and the meetup location.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-two-player-character-coterie.ttrpg", "form": "DEF", "guidance": [], "id": "#vkRaOAwdTlR1ocYpki9xymB", "key": "Daniella “Ley Line” Newton (Vengeful Occultist)", "name": "Daniella “Ley Line” Newton (Vengeful Occultist)", "parent": null, "props": [{"name": "Clan", "type": "STRING", "value": "Caitiff", "vk": "scalar"}, {"name": "Embraced", "type": "STRING", "value": "2017 (Born 1970)", "vk": "scalar"}, {"name": "Ambition", "type": "STRING", "value": "Create a unified theory of supernatural beings and events.", "vk": "scalar"}, {"name": "Predator", "type": "STRING", "value": "Cleaver", "vk": "scalar"}, {"name": "Convictions", "type": "STRING", "value": "The guilty must be punished.", "vk": "scalar"}, {"name": "Touchstones", "type": "STRING", "value": "Taylor Reed, last remaining mortal descendant of her sire.", "vk": "scalar"}, {"name": "Humanity", "type": "STRING", "value": "7", "vk": "scalar"}, {"name": "Generation", "type": "STRING", "value": "12th", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "1", "vk": "scalar"}, {"name": "Attributes", "type": "STRING", "value": "Strength 1, Dexterity 2, Stamina 2; Charisma 2, Manipulation 2, Composure 2; Intelligence 3, Wits 3, Resolve 4", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 5, Willpower 6", "vk": "scalar"}, {"name": "Skills", "type": "STRING", "value": "Athletics 2, Firearms 2, Stealth (Hiding) 1, Insight 3, Subterfuge (Coverups) 2, Academics (Teaching) 3, Awareness 3, Investigation 1, Medicine 1, Occult 4", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Animalism 1 (Bond Famulus: Bobbi, family Great Dane), Blood Sorcery 2 (A Taste for Blood, Extinguish Vitae), Celerity 1 (Rapid Reflexes)", "vk": "scalar"}, {"name": "Advantages", "type": "STRING", "value": "Linguistics (German, French, Spanish) 3, Haven (Family Guest Home: Good Size) 2, Herd 2, Resources 2", "vk": "scalar"}, {"name": "Flaws", "type": "STRING", "value": "Dark Secret (Cleaver) 1, Suspect", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vlbPlOBNb6yGpRb6Wqn0GQW": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "If the coterie doesn’t immediately break into violence, read out or paraphrase:\n\n*A hush falls over the gathering. Then come the murmurs.*\n\n*“Who the hell are these people?” “Archangel’s security must be terrible!” “Oh, these Anarchs are in for it now.”*\n\n*The big Latino man — you know him as Paul, the Sheriff — stands up. “That’s far enough.”*\n\n*A tall white man with long blond hair and a chiseled jaw stands up. That’s Archangel.*\n\n*“Well,” he says, “Before I was rudely interrupted—”*\n\n*The Latine announcer with the wiry brown hair holds up their hand. “Heard something on the wind about this. I want to see where this goes.”*\n\n*“What?!” Archangel’s rage shocks the crowd. “With all due respect, Herald…”*\n\n*“‘Avery,’ Archangel, thank you,” they say. They turn to you. “What does Captain’s merry band want with us now?”*\n\n*What do you do?*\n\nAvery’s only a Herald for the reclusive Prince of the city, but the Camarilla treat their word as if it were the Prince’s law. It’s by that word that the coterie won’t get thrown out in the cold or staked in front of an open window at this moment.\n\nArchangel is furious, even more so if a character he thought he captured is standing with the coterie. He gestures to his guards, who get ready.\n\nThis is the moment of truth. The coterie’s plans could fall into one of these three categories or could end up as a mixture of them. This story can’t account for every plan a table could create, but these should be the most common.\n\nIf the coterie killed any Kindred at the Blue Moon, Archangel can use this information once as a +1 Willpower damage weapon in any of the Social Conflicts below.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-five-tumbling-down.ttrpg", "form": "DEF", "guidance": [], "id": "#vlbPlOBNb6yGpRb6Wqn0GQW", "key": "Chapter Five: Tumbling Down", "name": "Chapter Five: Tumbling Down", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vmXkBxCDkVJek5WS3R1F9ON": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "take Archangel down, the players have the rest of the night (or a few hours, if the meeting’s later that night) to follow up on evidence or prepare for the challenge to come. If some members of the coterie were captured in **Chapter Two**, they have their own concerns.\n\nTake some time to talk with your players about the next steps their coterie wants to take. This chapter is less of a scene and more of an opportunity for players to plan (and a good place to adjust for time, either by roleplaying interactions and introducing complications, or speeding things up by zooming out). Their initial ideas might have changed since the start of the story, and it’s possible that what they want to do with (or to) Archangel shifted; for convention play, the pre-generated characters have Convictions that prompt them to react differently to what they’ve just seen and what they’re about to do.\n\nWhen the players are ready to go, start **Chapter Four.**", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "form": "DEF", "guidance": [], "id": "#vmXkBxCDkVJek5WS3R1F9ON", "key": "Chapter Three: All About Archangel", "name": "Chapter Three: All About Archangel", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vmid1eRAWZzAODwTA2bIeeB": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "Archangel’s a fool, a walking Masquerade breach, and better serves the Kindred as dust. The coterie decides that killing him is the only option.\n\nStarting a fight in Elysium is a bad idea. Starting a fight in a room with socially and physically powerful vampires like the Camarilla upper crust is a terrible idea. But, if anyone’s willing to commit to terrible ideas, it’s vampires. This is a Physical Conflict, and there’s no turning back.\n\nAt minimum, the coterie faces Archangel, whatever guards he has left, and Paul. If that’s not enough, the Sheriff has up to three hounds, who use the unaltered Anarch Revolutionary stat block. All combatants aim to kill the coterie or put them in Torpor.\n\nThe conflict lasts for three rounds. The coterie succeeds in killing Archangel if they either net three critical wins on him, decapitate him, or get at least one critical win on him after putting him in Torpor. If they can’t do this after the third round, there aren’t any more chances. Archangel’s allies help him escape from the VIP room, and the coterie must either fight their way out of the club or go down swinging.\n\nMake the consequences of this very clear to the players if they go this route. This might not be appropriate for a chronicle opener, but it could make for a fantastic one-shot climax; use any of the Vampire Antagonist templates (*Vampire: The Masquerade***,** p. 374) or stat blocks from Appendix One (p. 27) to allow the coterie to play the fight out if there’s time. If the players aren’t willing to risk parting with their characters, suggest exposing or capturing Archangel instead.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-five-tumbling-down.ttrpg", "form": "DEF", "guidance": [], "id": "#vmid1eRAWZzAODwTA2bIeeB", "key": "Killing Archangel", "name": "Killing Archangel", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vp6ZGwtmyNyGiawes8nzis6": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "If Adriana and her Kindred buddies know that the coterie are Anarchs or can’t be convinced that they aren’t, there’s still a chance at de-escalation. A Charisma + Leadership (Difficulty 3), Manipulation + Intimidation (Difficulty 4), or Wits + Politics (Difficulty 5) test either scares them into parley, convinces them that they’re worth listening to, or reminds them of the tense peace between the sects. Invoking the name of a Mawla, describing the threat “Michael’s” actions pose to her or to himself, or bearing fangs or using Presence on an unaccompanied Adriana can all reduce the Difficulty of an appropriate test. A critical win here also either gives the coterie a +1 dice bonus for the coming conflict or defuses all hostilities, at the Storyteller’s discretion. Proceed to *Social Conflict (*p. 17).", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-two-busted.ttrpg", "form": "DEF", "guidance": [], "id": "#vp6ZGwtmyNyGiawes8nzis6", "key": "Deescalating", "name": "Deescalating", "parent": "#vKH2yWMDJrQdYj7OFAQ9AAR", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vrcP9gF3O5SZ88I0wxoKown": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "The Waterfall Parlor has an opulent interior. In the center, a band plays jazzy renditions of classical music standards on the center stage, behind the titular waterfall. The tables and bar around the stage are reserved for the mortals and ghouls; the real event is in the VIP room. Adriana is at a table near the center stage if she’s still alive after **Chapter Two.** If she wasn’t turned to the coterie’s side, she could alert the authorities if she spots the coterie.\n\nThere’s a ghoul guard at the VIP room door, which is the only way in to the Primogen meeting. Unless the security detail, the bouncer, or Archangel is aware the coterie’s here and have warned her about them, she’ll assume the characters belong here if they have no Blush of Life. If characters are armed or clearly hostile, however, she has an opportunity to use notice them using Sense the Beast (**Vampire,** p. 245; as in *The Crowd Inside* but using Adriana’s stats for the ghoul), prompting her to alert some Kindred nearby who roughly escort the coterie into the meeting. Otherwise, entering this way means that someone’s going to catch them eventually, but the coterie can hold this off with either Obfuscate or a Wits + Stealth test at Difficulty 5. A win gives that character additional time to prepare for the confrontation in **Chapter Five**, and a win at a cost means that only Paul (p. 28) takes notice but chooses to hold back for now.\n\nInside the VIP room, the upper crust of the Camarilla meets. Avery (p. 28) leads the proceedings along with the current Primogen in the center of the room, with the rest of the city’s Kindred elite seated around them. Paul sits behind them. Archangel is seated as close to the Primogen as he can get. If any of his three goons from **Chapter Two** are still active and on his side, they’re nearby.\n\nIf undetected, the coterie watches Avery go over the meeting’s order of business, which begins with an “important announcement” from Archangel, who has an opportunity to notice them (likely after they get a little time to prepare, as described above). If only Paul notices them, he waits for the coterie to make a move before speaking up. If they’re caught immediately, or if they’ve physically attempted to force their way past the guard, all eyes fall on the coterie. **Chapter Five** begins.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-four-parlor-games.ttrpg", "form": "DEF", "guidance": [], "id": "#vrcP9gF3O5SZ88I0wxoKown", "key": "Inside Elysium", "name": "Inside Elysium", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vsvbZBIHPmkJnD6wLFaNDGA": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "If time is running short, the Storyteller can skip the tests here and give characters the relevant information from Table 2 (p. 14) regarding the evidence they’ve collected.\n\nIf the coterie has pictures of the captives and the corpses in the basement, an Intelligence + Academics test at Difficulty 3 reveals that each one of them went missing in the city sometime during the past few months. There’s no obvious pattern aside from visiting the Blue Moon somewhere between a week to a couple of days before their disappearance. If the coterie released some of the prisoners, they’ll make the news tomorrow.\n\nIf the coterie took pictures of the blood bags (or has some on hand), examining the labels with an Intelligence + Occult test at Difficulty 2 reveals that the ingredients described are being used for alchemical experiments designed to preserve blood and make it palatable to any Kindred regardless of age or clan. The earliest sample comes from three months ago.\n\nThe coterie can call Snap using the burner phone to report their findings and ask about the thin-blood alchemy. Snap isn’t horrified by the operation itself but is shocked at its scope. There’s a tone of disappointment in their voice when they talk about the thin-blooded alchemists involved. A Wits + Insight test at Difficulty 2 confirms that Snap not only knows the thin-blooded that created the sauce but is also convinced that they’re working with Archangel willingly. If confronted, they promise that they’ll deal with the sauce’s creators when this is over. If characters discovered the thin-blood corpse, Snap will confirm their suspicions.\n\nIn a longer chronicle, the Storyteller can devise similar tests to research evidence more deeply, possibly revealing connections to existing plot or character elements such as relationships between characters and any captured mortals or missing thin-blooded.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-three-all-about-archangel.ttrpg", "form": "DEF", "guidance": [], "id": "#vsvbZBIHPmkJnD6wLFaNDGA", "key": "Following Up", "name": "Following Up", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vuZI6YqLChYOLPaNbtdWfzM": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "The coterie has a few entry points:\n\nneeds a card and must go through a weapons check.\n\nElysium, but for convention play, the coterie should be reunited as soon as possible. If the coterie looks like they’re clearly armed or about to cause a scene, increase the Difficulty of all social tests to enter the Waterfall Parlor or to go unnoticed while there by 1.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-four-parlor-games.ttrpg", "form": "DEF", "guidance": [], "id": "#vuZI6YqLChYOLPaNbtdWfzM", "key": "Getting In", "name": "Getting In", "parent": null, "props": [{"items": [{"value": "Not every person with a golden business card, the Camarilla’s invitation, is a vampire. Some are ghouls or mortals in the know. Winning social tests, using an appropriate Discipline, or theft can get these cards. Every coterie member coming in through the front", "vk": "scalar"}, {"value": "The club’s mortal employees are working tonight. Characters can try to get their key cards by winning on a social test (perhaps a Performance or Subterfuge test to pose as caterers or entertainers), using an appropriate Discipline, or just stealing one. The electronic lock can be unlocked without a card with a Wits + Technology or Larceny test at Difficulty 4, which can be reduced with access to appropriate tools (*Equipment and Preparedness Tests*, p. 7) at the Storyteller’s discretion; winning at a cost might require a more substantial bribe or automatically alert Paul to their presence (*Inside Elysium*).", "vk": "scalar"}, {"value": "Evading the security detail to get to the greenroom is a Dexterity + Stealth test at Difficulty 5. It also has an electronic lock and needs the same test as the employee entrance.", "vk": "scalar"}, {"value": "If one or more of the coterie was captured in **Chapter Two**, they’re already inside. They begin the chapter inside the greenroom, staked and paralyzed, with an unknown Kindred standing over them, smiling mischievously. They’ll later recognize the Kindred as Avery Vega, the city’s Herald, but for now, they wrench the stake from the character’s heart. “And don’t let Captain say I never do anything for her,” they say on their way out. “I trust you’ll find a way to thank me. And soon.” In a longer chronicle, captured characters may have additional security measures to overcome or be Dominated to obey the rules of", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vvjGGE4ZJapNbxR8qTqJvgQ": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-three-adaptations.ttrpg", "form": "DEF", "guidance": [], "id": "#vvjGGE4ZJapNbxR8qTqJvgQ", "key": "Appendix Three: Adaptations", "name": "Appendix Three: Adaptations", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vwWp5HTSUrGO5nXb9dR8sVR": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "If this is a one-shot, the story ends here. If this is the start of a chronicle, award the coterie experience as normal (1–3 XP); successful groups may gain Captain as a Mawla (**Vampire,** p. 192) or buy the first dot of status with the Anarchs (or the Camarilla, depending on the outcome).\n\nHere’s some consequences that could lead to future stories.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-epilogue-domino-effect.ttrpg", "form": "DEF", "guidance": [], "id": "#vwWp5HTSUrGO5nXb9dR8sVR", "key": "Epilogue: Domino Effect", "name": "Epilogue: Domino Effect", "parent": null, "props": [{"items": [{"value": "If Archangel’s destroyed, there’s still a power vacuum in the city’s Primogen. Camarilla coteries resort to bigger and more blatant displays of power, eventually fracturing the peace and heating up the war between the Camarilla and Anarchs.", "vk": "scalar"}, {"value": "If Archangel’s in the coterie’s custody, they have a powerful bargaining chip. He’s also remorseful about his actions and even seems interested in learning about the Anarchs. Is he a potential convert, or is he just biding his time?", "vk": "scalar"}, {"value": "If Archangel’s disgraced and in exile, the coterie’s made a powerful enemy. In another city, he takes power and tries to start a war between his new domain and the coterie’s. He might even give in to his darker nature, abandoning his lineage and joining the shadowy sect known as the Sabbat.", "vk": "scalar"}, {"value": "If the coterie’s plans didn’t succeed, Archangel’s lying his way through the Camarilla’s investigation in hopes of becoming Primogen. Just when it looks like he might take the seat, he suddenly vanishes. His FBI contact found him, and now FIRSTLIGHT’s setting up shop.", "vk": "scalar"}, {"value": "Even if Archangel is defeated, his (albeit compromised) operation doesn’t just vanish. And neither do the thin-blood alchemists and other reluctant Anarchs who were counting on his promised favors as Primogen. Their revenge could be an obstacle to the coterie’s future endeavors, or they could become allies should the coterie want to take over some aspect of Archangel’s old business.", "vk": "scalar"}, {"value": "If the coteries’ investigation at the Blue Moon resulted in them leaving any evidence behind, Archangel’s contacts with local authorities could put FIRSTLIGHT on the coterie’s trail.", "vk": "scalar"}, {"value": "If any of the coterie were rescued by Avery, the Herald won’t take long to call in that favor, especially if they failed to dispose of Archangel. This section contains descriptions of major characters in the story. For any characters in the story not mentioned here, assume a General Difficulty of 2/2 and a 4 in all dice pools. Discipline ratings in this section don’t have powers attached to their dots. Feel free to choose what Discipline powers each dot has the first time the vampire uses it; for instance, Archangel’s security at the Blue Moon would benefit from having Sense the Beast, and Archangel’s Presence could be used to Daunt or Awe a captured character, or for a longer scene, affix the character with a Dread Gaze.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vwZ6vhhAZ3g6TwbFFOrWhDd": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "If the coterie convinces them to put the weapons down long enough to talk, they enter a Social Conflict.\n\nAdriana does most of the talking here. The ghoul attacks by insisting that that this project is all for the greater good. It reduces a vampire’s need to hunt and provides enough blood so that everyone has a fair shot at getting some. Once he finds the right formula, she believes that her domitor’s project will change the world as the Kindred know it.\n\nThe three vampires don’t come anywhere close to her ideals and settle for insults and taunts. Their words hide their thin skin, and any social attack implying that they’re only petty servants to Archangel or Adriana counts as a +1 Willpower damage weapon. Evidence of the thin-blooded corpse counts as a +3 Willpower damage weapon against these opponents.\n\nThe coterie wins the conflict if Adriana and the vampire guards take more Willpower damage than them. They’re willing to make a deal with the coterie: they’ll let them get out untouched if they don’t tell anyone anything. It’s a bad deal and they know it, but the coterie’s proven their dominance. If any of them end the conflict Impaired, they might even consider betraying Archangel and siding with the coterie, at the Storyteller’s discretion; if this happens, they might agree to serve as *Back-Up* (p. 20) in the coming conflict with Archangel. Otherwise, winning Adriana and any accompanying Kindred over can be rewarded by granting access to additional evidence, adding one +1 or +2 weapon to the final conflict in Elysium, or giving the characters access to enough gold cards that they can all enter the Waterfall Parlor.\n\nIf the coterie loses the conflict, Adriana and the vampire guards waste no time and escalate to a Physical Conflict, aiming to throw them out and take any evidence they have with them.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-two-busted.ttrpg", "form": "DEF", "guidance": [], "id": "#vwZ6vhhAZ3g6TwbFFOrWhDd", "key": "Social Conflict", "name": "Social Conflict", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vwujkwfzTxlK1SThw27YHpZ": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "The basement door in the alleyway is watched over by a security camera. If the coterie doesn’t have the technological prowess to disable it (same rules as *The Crowd Inside,* p. 11), they have more options here. They could cover the camera with nearby objects like a trash can lid, making a Dexterity + Athletics test at Difficulty 3. Destroying the camera without being seen is a Strength + Stealth test at Difficulty 4; winning at a cost here attracts attention, but depending on the coteries’ actions in *The Old Men*, they may have established a cover story for their presence. Cutting the camera off from the rest of the power source is a Dexterity + Technology or Larceny test at Difficulty 3. Adriana notices that the outside camera feed’s blacked out soon, but these’ll buy the coterie enough time to get the door open and explore the basement.\n\nThe door’s locked with a set of three strong locks, two of which have clear signs of recent installation. Unlocking them all in succession is a Dexterity + Larceny test at Difficulty 4. If the cameras are still active and the coterie wants to try unlocking the door through the camera’s blind spot, the Difficulty increases to 5. Characters can win at a cost, possibly by leaving clear evidence of their presence behind or needing to Dominate or otherwise subdue a bystander. If subtlety isn’t in the coterie’s nature, any character with at least 4 Strength or using an appropriate Discipline can yank the door off its hinges. Installing new locks in an old door severely weakened its integrity. Failure here shortens the amount of actions they’re able to take in the basement before someone arrives to stop them.\n\nIf the camera’s on when the door’s open and they’re coming in, Adriana sees them on the feed and arrives to confront the players’ characters after they have time for two actions. An active effort to hide their faces buys the coterie time to explore the basement.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-one-the-blue-moon.ttrpg", "form": "DEF", "guidance": [], "id": "#vwujkwfzTxlK1SThw27YHpZ", "key": "The Lock Outside", "name": "The Lock Outside", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vwvCZU6owZbh7ADnB8ZToJW": {"aliases": null, "book": "primogens-gambit", "children": ["#vgQih0kDOhsgY0Qq4Dd0HeL", "#vPmk13eSwQOaw00uqmOQSWz"], "choices": [], "desc": "The staircase to the basement is right in front of them if they’re coming in from the back, and three doors down to the right if they’re coming in from the bar, bypassing a supply closet and an employee bathroom. As they enter the basement, read out or paraphrase:\n\n*The stairs creak as you make your way down. The soft but familiar scent of blood hits your nose. Then comes the sound of a mechanical drone punctuated by low moans and sobs. When you step into the basement, you see it: three people strapped to gurneys, their veins hooked up to blood-drawing machines. Two of them are unconscious, and the third is hanging on by a thread, looking up at you with near-lifeless eyes.*\n\n*There’s a fridge in the center of the room, and a door to your right with a single padlock. A rancid smell poorly covered by a cheap lemon scent comes from it. On your left, a computer quietly clicks. The sounds of the bar leak through the basement ceiling.*\n\n*What do you do?*\n\nThe basement is the operations center for Archangel’s Circulatory System branch, or what’s left of it. There’s some signs mortals may have been kept in residence here once, like a typical Circulatory System operation, but for now the place is operating more like a ghost kitchen, tapping mortals for blood that can only be sold to Baggers. Adriana selects targets in the bar and traps them down here, often with the help of Archangel’s security who Dominate targets but sometimes drugging them herself, hoping to please “Michael” by taking initiative. She’s in charge of maintaining the system during daylight hours and helps keep the captives in a semi-conscious state.\n\nThe basement has six empty gurneys, and plenty of space to add more. It’s clear to the coterie that Archangel’s planning on expanding.\n\nThere’s two cameras on each side of the room. If the system hasn’t already been disabled or otherwise dealt with, or if the characters have drawn attention to themselves as described above, Adriana catches them after the coterie completes two different actions. If the cameras are taken care of, she realizes the basement feed’s gone after three. If the whole network’s down or if she’s actively being distracted by a character upstairs, the coterie gets four actions before she acts. Actions set the clock for the scene, so time is the resource characters stand to lose if they want to win at a cost or try again with a different dice pool. The Storyteller can adjust the number and timing of these actions, possibly distributing them on a per-player basis to make sure spotlight time is distributed evenly in a convention setting.\n\nUnhooking the victims on the gurney safely is a Dexterity + Medicine test at Difficulty 2 or Intelligence + Streetwise at Difficulty 3; a critical success restores the victim to consciousness. Unhooking each victim is considered its own separate action. The victims can’t say much aside from mumbling questions about who the coterie is and if they’re with their tormentors. If left to their own devices, they’ll climb up the stairs and try to find help, which gets Adriana’s attention. Any character that feeds from them gets a hit of the narcotics Adriana’s pumped into them and suffers a −2 penalty to Physical dice pools until the end of the next scene.\n\nUnlocking the padlocked room is a Dexterity + Larceny test at Difficulty 4. If the coterie wins, they might wish they hadn’t. Two corpses are inside, one appearing freshly dead and the other in an advanced state of decay. With clear signs of poorly applied needles, there’s no test necessary to determine how these people died, but a test\n\nof Intelligence + Investigation or Medicine at Difficulty 4 reveals that the age of the decaying corpse doesn’t square with how long Archangel has owned the bar. That’s because it isn’t a normal corpse but the body of a thin-blooded vampire; the late stage of decomposition reflects the time that’s passed since their mortal existence ended.\n\nThe fridge isn’t locked. It contains blood bags labeled by age, lifestyle, and any drugs that might be in the blood. There’s also a tub of margarine with a piece of tape labeled “special sauce.” Examining the tub and winning an Intelligence + Occult test at Difficulty 3 reveals that the “sauce” is a work of alchemy, similar to a Defranctionate (**Vampire,** p. 285) elixir used to make fractionated plasma (medical “blood bags”) palatable to Kindred without the Iron Gullet merit (**Vampire,** p. 182). Only the thin-blooded can make something like that, and they’re not permitted in the city’s Camarilla. It was either stolen from a thin-blooded alchemist, or Archangel’s been making deals with Anarchs. A critical or high margin of success (+2) on this test prompts the character to examine the other strange detritus around the room (moldy spinach, various factory chemicals and bizarre garbage); Archangel definitely has thin-blooded alchemists working for him, and they’re trying to develop something new.\n\nThe computer is locked with a password. Adriana set it up, and it’s easier to circumvent than she realizes. An Intelligence + Technology test at Difficulty 3 cracks it, while a Wits + Investigation test at Difficulty 2 finds it written in a drawer on the computer’s desk, “Guardian1.” Actions to search the desk also turn up a golden business card that acts as an invitation to the Waterfall Parlor; the Storyteller can reward exceptional successes here with more cards, up to the number of characters in the Story. The computer contains all kinds of information about the operation. There’s a list of potential clients, a “payroll” of vampires and ghouls in on the project, and a spreadsheet detailing all the captives. Spending an additional action examining the computer (or uploading its contents for later study with a Wits + Technology test at Difficulty 2) also yields communications between Archangel and prospective clients promising ethically sourced, universally palatable bagged blood; it’s clear that’s not what he’s producing down here, and the clients are putting pressure on him to deliver what he’s promised. A critical or high margin of success on tests using the computer reveals some poorly encrypted files, consisting of correspondence between Archangel under a fake name (Michael Baxter) and an agent of the Special Affairs Division of the FBI. Archangel claims that he has important information about some missing persons cases in the city (some of which are in this very room), and the agent expresses interest.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-chapter-one-the-blue-moon.ttrpg", "form": "DEF", "guidance": [], "id": "#vwvCZU6owZbh7ADnB8ZToJW", "key": "The Basement", "name": "The Basement", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vzA3AqVJWVST52rzJrWZ5bX": {"aliases": null, "book": "primogens-gambit", "children": [], "choices": [], "desc": "They call her Captain because she was the first to lead the Anarchs into the city’s new status quo. The Gangrel’s pretty sure that it’s just as much teasing as it is a sign of respect. The thought of herself as a Baron terrifies her to the core, but when the Anarchs need someone to make the final decision, Monique’s willing to make the call. Out of respect for the Anarch principles of freedom and self-rule, she’s willing to let the coterie use whatever methods they can to take Brenton down.", "entries": [], "enum": null, "file": "vtm5e-0.5-primogens-gambit-appendix-one-allies-antagonists.ttrpg", "form": "DEF", "guidance": [], "id": "#vzA3AqVJWVST52rzJrWZ5bX", "key": "Monique “Captain” Russell", "name": "Monique “Captain” Russell", "parent": "#vF9hcCMAwKiXhj2ZRmvQkPG", "props": [{"name": "General Difficulty", "type": "STRING", "value": "4 / 2", "vk": "scalar"}, {"name": "Blood Potency", "type": "STRING", "value": "2", "vk": "scalar"}, {"name": "Standard Dice Pools", "type": "STRING", "value": "Physical 5, Social 5, Mental 4", "vk": "scalar"}, {"name": "Secondary Attributes", "type": "STRING", "value": "Health 5, Willpower 4", "vk": "scalar"}, {"name": "Exceptional Dice Pools", "type": "STRING", "value": "Athletics 7, Survival 6, Leadership 6, Subterfuge 6", "vk": "scalar"}, {"name": "Disciplines", "type": "STRING", "value": "Animalism 2, Fortitude 2, Protean 2", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}}, "src": "data/primogens-gambit.js"};var T=window.VTM5E=window.VTM5E||{books:{},entities:{},loaded:{}};
T.loaded[d.src]=true;T.books[d.book.id]=d.book;
for(var h in d.entities){T.entities[h]=d.entities[h];}})();
